// release-readiness.cs — The release readiness gate for the 1.0 sequence (#104).
//
// An executable checklist. A registry (.github/release-checklist.json) lists every item the maintainer
// must be able to answer before a tag: each item traces to a SPEC-000 / SPEC-002 acceptance criterion
// or to #104, belongs to one SPEC-000 section 8 group, and carries a severity per release profile
// (block | warn | skip). Three profiles exist: minor (every vX.Y.0 of the 1.0 sequence), rc
// (1.0.0-rc.N) and final (1.0.0). The data flow has two stages:
//
//   --collect    reads GitHub, GitHub Pages, SonarCloud, nuget.org and the checkout, and writes
//                facts.json (every answer with its source URL and retrieval time);
//   --evaluate   reads ONLY facts.json (and the optional sign-off file): offline, deterministic.
//   --evidence   renders the SPEC-000 AC-022 evidence report from the same facts.json.
//
// Usage:
//   dotnet run --file .github/scripts/release-readiness.cs -- --check-registry [--registry <path>] [--root <dir>]
//   dotnet run --file .github/scripts/release-readiness.cs -- --from-branch release/v0.14.0
//   dotnet run --file .github/scripts/release-readiness.cs -- --collect (--version <v> --profile <p> | --from-branch <b>)
//                [--sha <40 hex>] --out <facts.json>
//   dotnet run --file .github/scripts/release-readiness.cs -- --evaluate --facts <facts.json>
//                (--version <v> | --from-branch <b>) [--profile <p>] [--signoff <checklist.md>] [--only <id,id>]
//                [--max-facts-age-hours 24] [--now <ISO-8601>]
//   dotnet run --file .github/scripts/release-readiness.cs -- --evidence --facts <facts.json> [--signoff <checklist.md>]
//                [--now <ISO-8601>] --out <evidence.md>
//   dotnet run --file .github/scripts/release-readiness.cs -- --render-checklist --profile <p> --version <v>
//                [--format checklist|pr-body] [--facts <facts.json>] [--out <path>]
//   dotnet run --file .github/scripts/release-readiness.cs -- --self-test
//
// Exit codes: 0 pass; 1 at least one blocking item failed or is unanswered (or the facts were rejected:
// wrong version or profile, stale, unreadable); 2 usage error or an invalid registry.
//
// Profile from the branch name (--from-branch release/v<version>): a -rc.N prerelease maps to rc,
// exactly 1.0.0 maps to final, any other valid SemVer X.Y.0 without prerelease maps to minor. A name the
// tool cannot map (not release/v<semver>, build metadata, another prerelease, a patch version) is an
// error (exit 2), never the lightest profile: the gate fails closed.
//
// Facts file (schema 1):
//   { "schema": 1, "version": "0.14.0", "profile": "minor", "sha": "<40 hex>", "collectedAtUtc": "<ISO-8601>",
//     "collector": "github-actions | <gh login>",
//     "facts": { "<factKey>": { "value": <json>, "source": "<url>", "retrievedAtUtc": "<ISO-8601>",
//                               "attempts": <n>, "error": "<text, only when the fact could not be read>" } } }
// A fact with "error", or a missing fact, FAILS a block item (fail closed, AGENTS.md section 3). Facts
// collected for another version or profile, older than --max-facts-age-hours or from the future are
// rejected. For --evidence the evaluation time is the collection time unless --now is given, so the
// committed evidence.md can be regenerated byte for byte from the committed facts.json.
//
// Sign-off file (docs/releases/v<version>/checklist.md, rendered by --render-checklist). One line per manual item:
//   - [ ] <id> — <title> — evidence: <link>
// Ticked ("x") with an evidence link (https URL or #issue) is an answer; ticked without a link or unticked is
// unanswered, and an unanswered block item fails (PENDING). Two more line kinds:
//   - allow-open: #123 — reason       issue the maintainer accepts as still open in the release milestone
//   - disposition: codeql#12 — text   disposition of a medium finding (codeql#<n> or sonar:<key>), quoted in evidence
// Text inside HTML comments is ignored.
//
// Facts the Actions GITHUB_TOKEN cannot read (open secret-scanning alerts and open Dependabot alerts) come
// from a GitHub App token in the environment variable RELEASE_GATE_APP_TOKEN. So does the branch protection of
// main (SPEC-000 AC-020), which needs the App permission "Administration: Read-only"; when the token is missing
// or the call fails with 403/404 the fact carries an error that names this remedy and branch-protection-exact
// FAILs closed (no attestation exists for it). The workflow mints the token with
// actions/create-github-app-token from the variable RELEASE_GATE_APP_ID and the secret
// RELEASE_GATE_APP_PRIVATE_KEY; the App is read-only and installed only on this repository. The tool uses
// the token only for these three collectors. A missing token or a failing API call records the fact with an
// error and the item fails closed. The only fallback is the manual attestation items attest-secret-scanning
// and attest-dependabot: accepted only when the matching auto fact carries an error, and the evaluation
// output states that the attestation replaced the fact. Alert data is never committed by hand.
//
// Remote calls use `gh api` (REST only) or HttpClient with one retry helper: 3 attempts, exponential
// backoff, Retry-After and x-ratelimit-reset honoured. A failed fact is recorded with error, never omitted.
// Requires: .NET 10+ (C# 14 file-based app), `gh` on PATH for the GitHub facts.
#pragma warning disable CA1305, CA1310, CA1859, CA1852, CA1861, CA1869, CA2007

using System.Diagnostics;
using System.Globalization;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using System.Text.Json.Nodes;
using System.Text.RegularExpressions;

CultureInfo.DefaultThreadCurrentCulture = CultureInfo.InvariantCulture;
CultureInfo.CurrentCulture = CultureInfo.InvariantCulture;
Console.OutputEncoding = new UTF8Encoding(false);
return await Cli.RunAsync(args, Env.Real());

// =============================================================================================
// Command line
// =============================================================================================

sealed class UsageException(string message) : Exception(message);

sealed class Options
{
    static readonly string[] Flags = ["--check-registry", "--collect", "--evaluate", "--evidence", "--render-checklist", "--self-test"];
    static readonly string[] Valued = ["--registry", "--root", "--version", "--profile", "--sha", "--out", "--facts", "--signoff", "--only",
        "--max-facts-age-hours", "--now", "--format", "--repo", "--from-branch"];

    readonly HashSet<string> flags = new(StringComparer.Ordinal);
    readonly Dictionary<string, string> values = new(StringComparer.Ordinal);

    public static Options Parse(string[] args)
    {
        var o = new Options();
        for (var i = 0; i < args.Length; i++)
        {
            var a = args[i];
            if (Flags.Contains(a)) o.flags.Add(a);
            else if (Valued.Contains(a) && i + 1 < args.Length) o.values[a] = args[++i];
            else throw new UsageException($"unknown or incomplete argument '{a}'");
        }
        return o;
    }

    public bool Flag(string name) => flags.Contains(name);
    public string? Get(string name) => values.GetValueOrDefault(name);
    public string Require(string name) => Get(name) ?? throw new UsageException($"{name} is required");
    public int ModeCount => flags.Count;
}

sealed class Env
{
    public required TextWriter Out { get; init; }
    public required TextWriter Err { get; init; }
    public required string Cwd { get; init; }
    public required IRemote Remote { get; init; }
    public required TimeProvider Clock { get; init; }
    public required Func<TimeSpan, Task> Delay { get; init; }
    public required Func<string, string?> GetEnv { get; init; }
    public Func<Task<string>>? CollectorIdentity { get; init; }

    public static Env Real() => new()
    {
        Out = Console.Out,
        Err = Console.Error,
        Cwd = Directory.GetCurrentDirectory(),
        Remote = new RealRemote(),
        Clock = TimeProvider.System,
        Delay = Task.Delay,
        GetEnv = Environment.GetEnvironmentVariable,
        CollectorIdentity = RealRemote.IdentityAsync,
    };
}

static class Cli
{
    public const string DefaultRepo = "dlrivada/Encina";
    public const string AppTokenVariable = "RELEASE_GATE_APP_TOKEN";
    static readonly string[] Profiles = ["minor", "rc", "final"];

    public static async Task<int> RunAsync(string[] args, Env env)
    {
        try
        {
            var o = Options.Parse(args);
            if (o.ModeCount != 1 && !o.Has("--from-branch")) throw new UsageException("choose exactly one mode flag (--check-registry, --collect, --evaluate, --evidence, --render-checklist, --self-test) or --from-branch");
            if (o.Flag("--self-test")) return await SelfTest.RunAsync(env, o.Get("--root"));
            if (o.ModeCount == 0) return FromBranch(o, env);
            var root = o.Get("--root") ?? FindRepoRoot(env.Cwd);
            var registryPath = Path.GetFullPath(o.Get("--registry") ?? Path.Combine(root, ".github", "release-checklist.json"));
            if (o.Flag("--check-registry")) return CheckRegistry(registryPath, root, env);
            var load = Registry.Load(registryPath, root);
            if (load.Errors.Count > 0) return RegistryFailure(load.Errors, registryPath, env);
            var reg = load.Registry!;
            if (o.Flag("--collect")) return await Collect(o, reg, root, env);
            if (o.Flag("--evaluate")) return Evaluate(o, reg, env);
            if (o.Flag("--evidence")) return EvidenceCommand(o, reg, env);
            return Render(o, reg, env);
        }
        catch (UsageException ex)
        {
            env.Err.WriteLine($"error: {ex.Message}");
            env.Err.WriteLine("usage: see the header of .github/scripts/release-readiness.cs");
            return 2;
        }
    }

    static bool Has(this Options o, string name) => o.Get(name) is not null;

    static int FromBranch(Options o, Env env)
    {
        var (version, profile) = BranchMap.Map(o.Require("--from-branch"));
        env.Out.WriteLine($"version={version}");
        env.Out.WriteLine($"profile={profile}");
        return 0;
    }

    // --version/--profile or --from-branch. The profile is null when only --version was given.
    static (string Version, string? Profile) ResolveVersion(Options o)
    {
        var branch = o.Get("--from-branch");
        if (branch is not null)
        {
            if (o.Get("--version") is not null) throw new UsageException("use --from-branch or --version, not both");
            var (v, p) = BranchMap.Map(branch);
            var explicitProfile = o.Get("--profile");
            if (explicitProfile is not null && explicitProfile != p) throw new UsageException($"--profile {explicitProfile} contradicts the profile {p} derived from the branch");
            return (v, p);
        }
        var version = o.Require("--version");
        if (!SemVer.IsValid(version)) throw new UsageException($"--version '{version}' is not valid SemVer 2.0.0");
        var profile = o.Get("--profile");
        if (profile is not null && !Profiles.Contains(profile)) throw new UsageException($"--profile must be one of {string.Join(", ", Profiles)}");
        return (version, profile);
    }

    static DateTimeOffset? ParseNow(Options o)
    {
        var raw = o.Get("--now");
        if (raw is null) return null;
        return Time.Parse(raw) ?? throw new UsageException($"--now must be an ISO 8601 timestamp, got '{raw}'");
    }

    public static string FindRepoRoot(string start)
    {
        var dir = new DirectoryInfo(Path.GetFullPath(start));
        while (dir is not null)
        {
            var git = Path.Combine(dir.FullName, ".git");
            if (Directory.Exists(git) || File.Exists(git)) return dir.FullName;
            dir = dir.Parent;
        }
        return start;
    }

    static int RegistryFailure(List<string> errors, string path, Env env)
    {
        foreach (var e in errors) env.Err.WriteLine($"error: {path}: {e}");
        return 2;
    }

    static int CheckRegistry(string path, string root, Env env)
    {
        var load = Registry.Load(path, root);
        if (load.Errors.Count > 0) return RegistryFailure(load.Errors, path, env);
        var reg = load.Registry!;
        env.Out.WriteLine($"Registry OK: {path} ({reg.Items.Count} items, {reg.Items.Count(i => i.IsRetired)} retired)");
        return 0;
    }

    static async Task<int> Collect(Options o, Registry reg, string root, Env env)
    {
        var (version, profile) = ResolveVersion(o);
        if (profile is null) throw new UsageException("--collect needs --profile (or --from-branch)");
        var sha = o.Get("--sha") ?? await GitHead(root);
        if (!Regex.IsMatch(sha, "^[0-9a-f]{40}$")) throw new UsageException($"--sha must be 40 lowercase hex characters, got '{sha}'");
        var outPath = Path.GetFullPath(o.Require("--out"));
        var repo = o.Get("--repo") ?? DefaultRepo;
        var facts = await Collectors.CollectAsync(reg, new CollectCtx(env, repo, root, version, profile, sha, env.GetEnv(AppTokenVariable)));
        var identity = env.GetEnv("GITHUB_ACTIONS") == "true" ? "github-actions" : env.CollectorIdentity is { } id ? await id() : "unknown";
        FactsFile.Write(outPath, new FactsFile(1, version, profile, sha, Time.Format(env.Clock.GetUtcNow()), identity, facts));
        var failed = facts.Count(f => f.Value.Error is not null);
        env.Out.WriteLine($"Collected {facts.Count} facts ({failed} with an error) for v{version} ({profile}) at {sha[..12]} -> {outPath}");
        return 0;
    }

    static async Task<string> GitHead(string root)
    {
        var r = await Proc.RunAsync("git", ["-C", root, "rev-parse", "HEAD"], null);
        if (r.Code != 0) throw new UsageException("--sha was not given and `git rev-parse HEAD` failed");
        return r.Stdout.Trim();
    }

    static FactsFile? LoadFactsOrReject(Options o, Env env, string version, string? expectedProfile, bool checkAge, DateTimeOffset now, double maxHours)
    {
        FactsFile facts;
        try { facts = FactsFile.Read(Path.GetFullPath(o.Require("--facts"))); }
        catch (Exception ex) when (ex is IOException or JsonException or InvalidDataException)
        {
            env.Err.WriteLine($"REJECTED facts: unreadable ({ex.GetType().Name}: {ex.Message})");
            return null;
        }
        var problem = facts.Validate(version, expectedProfile, checkAge, now, maxHours);
        if (problem is null) return facts;
        env.Err.WriteLine($"REJECTED facts: {problem}");
        return null;
    }

    static int Evaluate(Options o, Registry reg, Env env)
    {
        var (version, profileFromBranch) = ResolveVersion(o);
        // Without --profile or --from-branch the profile is derived from the version, never taken from the facts.
        var expectedProfile = o.Get("--profile") ?? profileFromBranch ?? BranchMap.Map("release/v" + version).Profile;
        var now = ParseNow(o) ?? env.Clock.GetUtcNow();
        var maxHours = double.TryParse(o.Get("--max-facts-age-hours") ?? "24", NumberStyles.Float, CultureInfo.InvariantCulture, out var h) && h > 0 ? h : throw new UsageException("--max-facts-age-hours must be a number greater than 0");
        var facts = LoadFactsOrReject(o, env, version, expectedProfile, true, now, maxHours);
        if (facts is null) return 1;
        var signoff = LoadSignoff(o);
        var only = o.Get("--only")?.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToHashSet(StringComparer.Ordinal);
        if (only is not null)
        {
            var unknown = only.Where(id => reg.Items.All(i => i.Id != id)).ToList();
            if (unknown.Count > 0) throw new UsageException($"--only names unknown item id(s): {string.Join(", ", unknown)}");
        }
        var run = Engine.Run(reg, new EvalCtx(facts, signoff, now), only);
        env.Out.Write(Report.EvaluationText(run, facts));
        var summaryPath = env.GetEnv("GITHUB_STEP_SUMMARY");
        if (!string.IsNullOrWhiteSpace(summaryPath)) File.AppendAllText(summaryPath, Report.SummaryMarkdown(run, facts));
        return run.Passed ? 0 : 1;
    }

    static int EvidenceCommand(Options o, Registry reg, Env env)
    {
        var (version, profile) = ResolveVersionLoose(o);
        var outPath = Path.GetFullPath(o.Require("--out"));
        var facts = LoadFactsOrReject(o, env, version, profile, false, DateTimeOffset.UnixEpoch, 1);
        if (facts is null) return 1;
        var now = ParseNow(o) ?? Time.Parse(facts.CollectedAtUtc)!.Value;
        var run = Engine.Run(reg, new EvalCtx(facts, LoadSignoff(o), now), null);
        WriteText(outPath, Report.Evidence(reg, run, facts, LoadSignoff(o)));
        env.Out.WriteLine($"Evidence written: {outPath} (result {(run.Passed ? "PASS" : "FAIL")})");
        return 0;
    }

    // --evidence derives the version from the facts file when no version option is given.
    static (string Version, string? Profile) ResolveVersionLoose(Options o)
    {
        if (o.Get("--version") is not null || o.Get("--from-branch") is not null) return ResolveVersion(o);
        var facts = FactsFile.Read(Path.GetFullPath(o.Require("--facts")));
        return (facts.Version, o.Get("--profile"));
    }

    static Signoff LoadSignoff(Options o)
    {
        var path = o.Get("--signoff");
        if (path is null) return Signoff.Empty;
        if (!File.Exists(path)) throw new UsageException($"--signoff file not found: {path}");
        return Signoff.Parse(File.ReadAllText(path));
    }

    static int Render(Options o, Registry reg, Env env)
    {
        var version = o.Require("--version");
        var profile = o.Require("--profile");
        if (!SemVer.IsValid(version)) throw new UsageException($"--version '{version}' is not valid SemVer 2.0.0");
        if (!Profiles.Contains(profile)) throw new UsageException($"--profile must be one of {string.Join(", ", Profiles)}");
        var format = o.Get("--format") ?? "checklist";
        string text;
        if (format == "checklist") text = Report.Checklist(reg, version, profile);
        else if (format == "pr-body")
        {
            Signoff signoff = LoadSignoff(o);
            FactsFile? facts = o.Get("--facts") is null ? null : FactsFile.Read(Path.GetFullPath(o.Require("--facts")));
            EvalRun? run = facts is null ? null : Engine.Run(reg, new EvalCtx(facts, signoff, Time.Parse(facts.CollectedAtUtc)!.Value), null);
            text = Report.PrBody(version, profile, run);
        }
        else throw new UsageException("--format must be checklist or pr-body");
        var outPath = o.Get("--out");
        if (outPath is null) env.Out.Write(text);
        else
        {
            WriteText(Path.GetFullPath(outPath), text);
            env.Out.WriteLine($"Rendered {format}: {outPath}");
        }
        return 0;
    }

    static void WriteText(string path, string text)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        File.WriteAllText(path, text, new UTF8Encoding(false));
    }
}

// =============================================================================================
// SemVer, branch mapping, time
// =============================================================================================

static class SemVer
{
    static readonly Regex Pattern = new(@"^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$", RegexOptions.CultureInvariant);

    public static bool IsValid(string v) => Pattern.IsMatch(v);

    public static (int Major, int Minor, int Patch, string Pre, string Build)? Parse(string v)
    {
        var m = Pattern.Match(v);
        if (!m.Success) return null;
        return (int.Parse(m.Groups[1].Value), int.Parse(m.Groups[2].Value), int.Parse(m.Groups[3].Value), m.Groups[4].Value, m.Groups[5].Value);
    }
}

static class BranchMap
{
    // Fail closed: a name that cannot be mapped is a usage error, never the lightest profile.
    public static (string Version, string Profile) Map(string branch)
    {
        const string prefix = "release/v";
        if (!branch.StartsWith(prefix, StringComparison.Ordinal)) throw new UsageException($"branch '{branch}' does not match release/v<version>; the profile cannot be derived");
        var version = branch[prefix.Length..];
        var sv = SemVer.Parse(version) ?? throw new UsageException($"branch '{branch}': '{version}' is not valid SemVer 2.0.0");
        if (sv.Build.Length > 0) throw new UsageException($"branch '{branch}': build metadata is not allowed in a release version");
        if (sv.Pre.Length > 0)
            return Regex.IsMatch(sv.Pre, @"^rc\.(0|[1-9]\d*)$") ? (version, "rc") : throw new UsageException($"branch '{branch}': prerelease '{sv.Pre}' is not rc.N");
        if (version == "1.0.0") return (version, "final");
        if (sv.Patch == 0) return (version, "minor");
        throw new UsageException($"branch '{branch}': patch version {version} is outside the 1.0 sequence profiles");
    }
}

static class Time
{
    public static DateTimeOffset? Parse(string raw) =>
        DateTimeOffset.TryParse(raw, CultureInfo.InvariantCulture, DateTimeStyles.AssumeUniversal | DateTimeStyles.AdjustToUniversal, out var t) ? t : null;

    public static string Format(DateTimeOffset t) => t.UtcDateTime.ToString("yyyy-MM-ddTHH:mm:ssZ", CultureInfo.InvariantCulture);
}

// =============================================================================================
// Registry model, loading and validation (--check-registry)
// =============================================================================================

sealed record Item(string Id, string Title, IReadOnlyList<string> Sources, IReadOnlyList<int> Owner, string Kind, string Group,
    string? CheckName, JsonObject Params, IReadOnlyDictionary<string, string> Profiles, string? RetiredReason, string? RetiredRef, string? Attests)
{
    public bool IsRetired => RetiredReason is not null;
    public string SeverityFor(string profile) => Profiles.GetValueOrDefault(profile, "skip");
}

sealed record SpecRef(string Id, string Path, string Ids);

sealed record Registry(IReadOnlyList<SpecRef> Specs, IReadOnlyList<Item> Items)
{
    public static readonly string[] Groups = ["Inventory", "Build and quality gates", "Defects and security", "API and docs", "Release", "Evidence", "Regulatory compliance and readiness"];
    static readonly string[] Kinds = ["auto", "issue-state", "manual"];
    static readonly string[] Severities = ["block", "warn", "skip"];
    static readonly string[] ProfileNames = ["minor", "rc", "final"];

    public sealed record LoadResult(Registry? Registry, List<string> Errors);

    public static LoadResult Load(string path, string root)
    {
        var errors = new List<string>();
        string text;
        try { text = File.ReadAllText(path); }
        catch (IOException ex) { return new LoadResult(null, [$"could not read the registry: {ex.Message}"]); }
        return Parse(text, root, errors);
    }

    public static LoadResult Parse(string text, string root, List<string> errors)
    {
        JsonNode? node;
        try { node = JsonNode.Parse(text); }
        catch (JsonException ex) { return new LoadResult(null, [$"registry is not valid JSON: {ex.Message}"]); }
        if (node is not JsonObject obj) return new LoadResult(null, ["registry root must be an object"]);
        if (!(obj["schema"] is JsonValue sv && sv.TryGetValue<int>(out var schema) && schema == 1)) errors.Add("'schema' must be 1");
        var specs = ParseSpecs(obj["specs"], errors);
        var items = new List<Item>();
        if (obj["items"] is not JsonArray arr) errors.Add("'items' must be an array");
        else
        {
            var seen = new HashSet<string>(StringComparer.Ordinal);
            for (var i = 0; i < arr.Count; i++)
                if (ParseItem(arr[i], i, seen, errors) is { } item) items.Add(item);
        }
        ValidateCrossReferences(items, errors);
        ValidateSpecCoverage(specs, items, root, errors);
        return new LoadResult(errors.Count == 0 ? new Registry(specs, items) : null, errors);
    }

    static List<SpecRef> ParseSpecs(JsonNode? node, List<string> errors)
    {
        var list = new List<SpecRef>();
        if (node is not JsonArray arr) { errors.Add("'specs' must be an array"); return list; }
        foreach (var s in arr)
        {
            var id = Str(s?["id"]);
            var path = Str(s?["path"]);
            var ids = Str(s?["ids"]);
            if (id is null || !Regex.IsMatch(id, @"^SPEC-\d{3}$")) errors.Add($"specs entry needs an id like SPEC-000 (got '{id}')");
            else if (path is null || path.Length == 0) errors.Add($"specs entry {id} needs a path");
            else if (ids is null || !(ids == "all" || Regex.IsMatch(ids, @"^AC-\d{3}\.\.AC-\d{3}$"))) errors.Add($"specs entry {id}: 'ids' must be \"all\" or \"AC-nnn..AC-nnn\"");
            else if (list.Any(x => x.Id == id)) errors.Add($"duplicate specs entry {id}");
            else list.Add(new SpecRef(id, path, ids));
        }
        return list;
    }

    static Item? ParseItem(JsonNode? node, int index, HashSet<string> seen, List<string> errors)
    {
        var where = $"items[{index}]";
        if (node is not JsonObject o) { errors.Add($"{where} must be an object"); return null; }
        var id = Str(o["id"]);
        if (id is null || !Regex.IsMatch(id, "^[a-z0-9]+(-[a-z0-9]+)*$")) { errors.Add($"{where}.id must be kebab-case (got '{id}')"); return null; }
        where = $"item '{id}'";
        if (!seen.Add(id)) { errors.Add($"duplicate item id '{id}'"); return null; }
        var before = errors.Count;
        var title = Str(o["title"]);
        if (string.IsNullOrWhiteSpace(title)) errors.Add($"{where}: 'title' is required");
        var sources = StrList(o["source"]);
        if (sources.Count == 0) errors.Add($"{where}: 'source' needs at least one reference");
        var owners = new List<int>();
        if (o["owner"] is JsonArray oa) foreach (var x in oa) { if (x is JsonValue v && v.TryGetValue<int>(out var n)) owners.Add(n); else errors.Add($"{where}: 'owner' entries must be issue numbers"); }
        else if (o["owner"] is not null) errors.Add($"{where}: 'owner' must be an array");
        var kind = Str(o["kind"]);
        if (kind is null || !Kinds.Contains(kind)) errors.Add($"{where}: 'kind' must be one of {string.Join(", ", Kinds)}");
        var group = Str(o["group"]);
        if (group is null || !Groups.Contains(group)) errors.Add($"{where}: 'group' must be one of the SPEC-000 section 8 groups: {string.Join("; ", Groups)}");

        string? retiredReason = null, retiredRef = null;
        if (o["retired"] is JsonObject r)
        {
            retiredReason = Str(r["reason"]);
            retiredRef = Str(r["ref"]);
            if (string.IsNullOrWhiteSpace(retiredReason)) errors.Add($"{where}: a retired item needs retired.reason");
            if (string.IsNullOrWhiteSpace(retiredRef)) errors.Add($"{where}: a retired item needs retired.ref");
            retiredReason ??= "";
        }
        else if (o["retired"] is not null) errors.Add($"{where}: 'retired' must be an object");

        var profiles = new Dictionary<string, string>(StringComparer.Ordinal);
        if (o["profiles"] is JsonObject po)
        {
            foreach (var name in ProfileNames)
            {
                var sev = Str(po[name]);
                if (sev is null || !Severities.Contains(sev)) errors.Add($"{where}: profiles.{name} must be one of {string.Join(", ", Severities)}");
                else profiles[name] = sev;
            }
        }
        else if (retiredReason is null) errors.Add($"{where}: 'profiles' is required");

        string? checkName = null;
        var parameters = new JsonObject();
        if (kind is "auto" or "issue-state" && retiredReason is null)
        {
            if (o["check"] is not JsonObject chk) errors.Add($"{where}: kind {kind} needs a 'check'");
            else
            {
                checkName = Str(chk["name"]);
                parameters = chk["params"] as JsonObject ?? new JsonObject();
                if (checkName is null || !Evaluators.Table.TryGetValue(checkName, out var def)) errors.Add($"{where}: unknown evaluator '{checkName}'");
                else
                {
                    foreach (var e in ParamSpec.Validate(def.ParamSpec, parameters)) errors.Add($"{where}: check.params {e}");
                    if (kind == "issue-state" && checkName != "issue-state") errors.Add($"{where}: kind issue-state requires the issue-state evaluator");
                }
            }
        }
        else if (kind == "manual" && o["check"] is not null) errors.Add($"{where}: a manual item has no 'check'");

        var attests = Str(o["attests"]);
        if (errors.Count > before) return null;
        return new Item(id, title!, sources, owners, kind!, group!, checkName, parameters, profiles, retiredReason, retiredRef, attests);
    }

    static void ValidateCrossReferences(List<Item> items, List<string> errors)
    {
        var byId = items.ToDictionary(i => i.Id, StringComparer.Ordinal);
        foreach (var item in items.Where(i => !i.IsRetired))
        {
            if (item.Attests is not null)
            {
                if (item.Kind != "manual") errors.Add($"item '{item.Id}': only a manual item can attest");
                else if (!byId.TryGetValue(item.Attests, out var t) || t.Kind == "manual" || t.CheckName == "alias") errors.Add($"item '{item.Id}': attests '{item.Attests}', which is not an auto item");
            }
            if (item.CheckName != "alias") continue;
            var target = item.Params["item"]?.GetValue<string>();
            if (target is null || !byId.TryGetValue(target, out var targetItem) || targetItem.IsRetired || targetItem.Kind == "manual" || targetItem.CheckName == "alias")
            {
                errors.Add($"item '{item.Id}': alias target '{target}' must be an active non-alias auto item");
                continue;
            }
            foreach (var p in item.Profiles.Where(p => p.Value != "skip" && targetItem.SeverityFor(p.Key) == "skip"))
                errors.Add($"item '{item.Id}': alias is active in {p.Key} but its target '{target}' is skipped there");
        }
    }

    // The acceptance-criterion ids are read from the SPEC files at run time, never hard-coded.
    static void ValidateSpecCoverage(List<SpecRef> specs, List<Item> items, string root, List<string> errors)
    {
        var cited = new HashSet<string>(StringComparer.Ordinal);
        foreach (var item in items)
            foreach (var s in item.Sources.Where(s => Regex.IsMatch(s, @"^SPEC-\d{3} AC-\d{3}$")))
                if (item.IsRetired || item.Profiles.Count > 0) cited.Add(s);
        var known = new HashSet<string>(StringComparer.Ordinal);
        foreach (var spec in specs)
        {
            var full = Path.IsPathRooted(spec.Path) ? spec.Path : Path.Combine(root, spec.Path);
            if (!File.Exists(full)) { errors.Add($"spec file for {spec.Id} not found: {spec.Path}"); continue; }
            var all = File.ReadAllLines(full).Select(l => Regex.Match(l, @"^\|\s*(AC-\d{3})\s*\|")).Where(m => m.Success).Select(m => m.Groups[1].Value).ToList();
            foreach (var ac in all) known.Add($"{spec.Id} {ac}");
            foreach (var ac in all.Where(a => InRange(spec.Ids, a)).Where(ac => !cited.Contains($"{spec.Id} {ac}")))
                errors.Add($"{spec.Id} {ac} has no registry entry or retired record");
        }
        foreach (var c in cited.Where(c => !known.Contains(c)))
            errors.Add($"source '{c}' is not an acceptance criterion of a listed spec file");
    }

    static bool InRange(string range, string ac)
    {
        if (range == "all") return true;
        var parts = range.Split("..");
        var n = int.Parse(ac[3..]);
        return n >= int.Parse(parts[0][3..]) && n <= int.Parse(parts[1][3..]);
    }

    static string? Str(JsonNode? n) => n is JsonValue v && v.TryGetValue<string>(out var s) ? s : null;

    static List<string> StrList(JsonNode? n) => n is JsonArray a ? a.Select(Str).Where(s => !string.IsNullOrWhiteSpace(s)).Select(s => s!).ToList() : [];
}

static class ParamSpec
{
    // Spec text: "name:type;other?:type" where type is s (string), i (int), n (number), b (bool), s[] or i[]; a trailing ? makes the name optional.
    public static List<string> Validate(string spec, JsonObject p)
    {
        var errors = new List<string>();
        var declared = new HashSet<string>(StringComparer.Ordinal);
        foreach (var part in spec.Split(';', StringSplitOptions.RemoveEmptyEntries))
        {
            var kv = part.Split(':');
            var optional = kv[0].EndsWith('?');
            var name = kv[0].TrimEnd('?');
            declared.Add(name);
            var v = p[name];
            if (v is null) { if (!optional) errors.Add($"is missing '{name}'"); continue; }
            if (!Matches(kv[1], v)) errors.Add($"'{name}' must be of type {kv[1]}");
        }
        foreach (var extra in p.Select(x => x.Key).Where(k => !declared.Contains(k))) errors.Add($"has unknown parameter '{extra}'");
        return errors;
    }

    static bool Matches(string type, JsonNode v) => type switch
    {
        "s" => v is JsonValue sv && sv.TryGetValue<string>(out _),
        "i" => v is JsonValue iv && iv.TryGetValue<int>(out _),
        "n" => v is JsonValue nv && nv.TryGetValue<double>(out _),
        "b" => v is JsonValue bv && bv.TryGetValue<bool>(out _),
        "s[]" => v is JsonArray sa && sa.All(x => x is JsonValue xv && xv.TryGetValue<string>(out _)),
        "i[]" => v is JsonArray ia && ia.All(x => x is JsonValue xv && xv.TryGetValue<int>(out _)),
        _ => false,
    };
}

// =============================================================================================
// Facts file and sign-off file
// =============================================================================================

sealed record Fact(JsonNode? Value, string Source, string RetrievedAtUtc, string? Error, int Attempts);

sealed record FactsFile(int Schema, string Version, string Profile, string Sha, string CollectedAtUtc, string Collector, IReadOnlyDictionary<string, Fact> Facts)
{
    public static FactsFile Read(string path)
    {
        var root = JsonNode.Parse(File.ReadAllText(path)) as JsonObject ?? throw new InvalidDataException("facts root must be an object");
        string Req(string name) => J.Str(root[name]) ?? throw new InvalidDataException($"facts file lacks '{name}'");
        var schema = J.Int(root["schema"]) ?? throw new InvalidDataException("facts file lacks 'schema'");
        var facts = new SortedDictionary<string, Fact>(StringComparer.Ordinal);
        foreach (var (key, node) in root["facts"] as JsonObject ?? throw new InvalidDataException("facts file lacks 'facts'"))
        {
            if (node is not JsonObject f) throw new InvalidDataException($"fact '{key}' must be an object");
            facts[key] = new Fact(f["value"]?.DeepClone(), J.Str(f["source"]) ?? "", J.Str(f["retrievedAtUtc"]) ?? "", J.Str(f["error"]), J.Int(f["attempts"]) ?? 1);
        }
        return new FactsFile(schema, Req("version"), Req("profile"), Req("sha"), Req("collectedAtUtc"), J.Str(root["collector"]) ?? "unknown", facts);
    }

    public static void Write(string path, FactsFile file)
    {
        var facts = new JsonObject();
        foreach (var (key, f) in file.Facts.OrderBy(k => k.Key, StringComparer.Ordinal))
        {
            var o = new JsonObject();
            if (f.Error is null) o["value"] = f.Value?.DeepClone();
            o["source"] = f.Source;
            o["retrievedAtUtc"] = f.RetrievedAtUtc;
            o["attempts"] = f.Attempts;
            if (f.Error is not null) o["error"] = f.Error;
            facts[key] = o;
        }
        var root = new JsonObject
        {
            ["schema"] = file.Schema, ["version"] = file.Version, ["profile"] = file.Profile, ["sha"] = file.Sha,
            ["collectedAtUtc"] = file.CollectedAtUtc, ["collector"] = file.Collector, ["facts"] = facts,
        };
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        File.WriteAllText(path, root.ToJsonString(new JsonSerializerOptions { WriteIndented = true, Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping }) + "\n", new UTF8Encoding(false));
    }

    // Returns the reason the facts cannot be used, or null. Fail closed: any doubt rejects.
    public string? Validate(string version, string? expectedProfile, bool checkAge, DateTimeOffset now, double maxHours)
    {
        if (Schema != 1) return $"schema {Schema} is not supported (expected 1)";
        if (Version != version) return $"facts were collected for version {Version}, not {version}";
        if (!new[] { "minor", "rc", "final" }.Contains(Profile)) return $"unknown profile '{Profile}'";
        if (expectedProfile is not null && Profile != expectedProfile) return $"facts were collected for profile {Profile}, not {expectedProfile}";
        if (!Regex.IsMatch(Sha, "^[0-9a-f]{40}$")) return $"sha '{Sha}' is not 40 lowercase hex characters";
        var at = Time.Parse(CollectedAtUtc);
        if (at is null) return $"collectedAtUtc '{CollectedAtUtc}' is not a timestamp";
        if (!checkAge) return null;
        if (at.Value - now > TimeSpan.FromHours(1)) return $"collectedAtUtc {CollectedAtUtc} is in the future";
        if ((now - at.Value).TotalHours > maxHours) return $"facts are stale: collected {CollectedAtUtc}, older than {maxHours} hours";
        return null;
    }
}

sealed record Answer(bool Ticked, string? Evidence);

sealed class Signoff
{
    public static readonly Signoff Empty = new();
    public Dictionary<string, Answer> Items { get; } = new(StringComparer.Ordinal);
    public List<int> AllowOpen { get; } = [];
    public SortedDictionary<string, string> Dispositions { get; } = new(StringComparer.Ordinal);

    public string? EvidenceOf(string id) => Items.TryGetValue(id, out var a) && a.Ticked ? a.Evidence : null;

    public static Signoff Parse(string text)
    {
        var s = new Signoff();
        var clean = Regex.Replace(text, "<!--.*?-->", "", RegexOptions.Singleline);
        foreach (var line in clean.Split('\n').Select(l => l.TrimEnd('\r')))
        {
            var m = Regex.Match(line, @"^- \[(?<t>[ xX])\]\s+(?<id>[a-z0-9]+(?:-[a-z0-9]+)*)(?<rest>.*)$");
            if (m.Success)
            {
                var ev = Regex.Match(m.Groups["rest"].Value, @"evidence:\s*(?<e>https?://\S+|#\d+)");
                s.Items[m.Groups["id"].Value] = new Answer(m.Groups["t"].Value != " ", ev.Success ? ev.Groups["e"].Value : null);
                continue;
            }
            var allow = Regex.Match(line, @"^- allow-open:\s*#(?<n>\d+)");
            if (allow.Success) { s.AllowOpen.Add(int.Parse(allow.Groups["n"].Value)); continue; }
            var disp = Regex.Match(line, @"^- disposition:\s*(?<ref>\S+)\s*[—–-]+\s*(?<text>.+)$");
            if (disp.Success) s.Dispositions[disp.Groups["ref"].Value] = disp.Groups["text"].Value.Trim();
        }
        return s;
    }
}

static class J
{
    public static string? Str(JsonNode? n) => n is JsonValue v && v.TryGetValue<string>(out var s) ? s : null;
    public static int? Int(JsonNode? n) => n is JsonValue v && v.TryGetValue<int>(out var i) ? i : null;
    public static long? Long(JsonNode? n) => n is JsonValue v && v.TryGetValue<long>(out var i) ? i : null;
    public static double? Num(JsonNode? n) => n is JsonValue v && v.TryGetValue<double>(out var d) ? d : null;
    public static bool? Bool(JsonNode? n) => n is JsonValue v && v.TryGetValue<bool>(out var b) ? b : null;
    public static JsonArray Arr(JsonNode? n) => n as JsonArray ?? [];
    public static IEnumerable<JsonObject> Objs(JsonNode? n) => Arr(n).OfType<JsonObject>();
    public static IEnumerable<string> Strs(JsonNode? n) => Arr(n).Select(Str).Where(s => s is not null).Select(s => s!);
    public static string Short(string sha) => sha.Length > 12 ? sha[..12] : sha;
    public static string Days(double d) => d.ToString("0.0", CultureInfo.InvariantCulture);
}

// =============================================================================================
// Evaluators: one small pure function over facts each. No clock reads, no network.
// =============================================================================================

enum OutcomeKind { Pass, Fail, Pending, NotNeeded }

readonly record struct Outcome(OutcomeKind Kind, string Reason)
{
    public static Outcome Pass(string r) => new(OutcomeKind.Pass, r);
    public static Outcome Fail(string r) => new(OutcomeKind.Fail, r);
    public static Outcome Pending(string r) => new(OutcomeKind.Pending, r);
    public static Outcome NotNeeded(string r) => new(OutcomeKind.NotNeeded, r);
}

sealed record FactRequest(string Key, string Collector, JsonObject Args);

sealed record EvalCtx(FactsFile Facts, Signoff Signoff, DateTimeOffset Now)
{
    public string Version => Facts.Version;
    public string Profile => Facts.Profile;
    public string Sha => Facts.Sha;
    public JsonNode? Value(string key) => Facts.Facts[key].Value;
}

sealed record EvalDef(string Name, string ParamSpec, Func<Item, string, IEnumerable<FactRequest>> Needs, Func<Item, EvalCtx, Outcome> Eval);

static class Evaluators
{
    public static readonly IReadOnlyDictionary<string, EvalDef> Table = Build();

    static string S(Item i, string k) => J.Str(i.Params[k]) ?? "";
    static string[] Ss(Item i, string k) => J.Strs(i.Params[k]).ToArray();
    static int[] Is(Item i, string k) => J.Arr(i.Params[k]).Select(J.Int).Where(x => x is not null).Select(x => x!.Value).ToArray();

    static FactRequest Req(string key, string collector, params (string, string)[] args)
    {
        var o = new JsonObject();
        foreach (var (k, v) in args) o[k] = v;
        return new FactRequest(key, collector, o);
    }

    static IReadOnlyDictionary<string, EvalDef> Build()
    {
        var list = new List<EvalDef>
        {
            new("ci-run", "workflow:s;events:s[]", (i, v) => [Req($"ci-run:{S(i, "workflow")}", "ci-run", ("workflow", S(i, "workflow")))], CiRun),
            new("workflow-latest", "workflow:s;maxAgeDays:n", (i, v) => [Req($"workflow-latest:{S(i, "workflow")}", "workflow-latest", ("workflow", S(i, "workflow")))], WorkflowLatest),
            new("code-scanning-alerts", "minSeverity:s", (i, v) => [Req("code-scanning-alerts", "code-scanning")], (i, c) => Alerts(c, "code-scanning-alerts", S(i, "minSeverity"), "alerts", "severity")),
            new("dependabot-alerts", "minSeverity:s", (i, v) => [Req("dependabot-alerts", "dependabot")], (i, c) => Alerts(c, "dependabot-alerts", S(i, "minSeverity"), "alerts", "severity")),
            new("secret-scanning-alerts", "", (i, v) => [Req("secret-scanning-alerts", "secret-scanning")], SecretAlerts),
            new("sonar-issues", "", (i, v) => [Req("sonar-issues", "sonar")], Sonar),
            new("issue-state", "issues:i[];require:s;label?:s", (i, v) => Is(i, "issues").Select(n => Req($"issue:{n}", "issue", ("number", n.ToString()))), IssueState),
            new("bug-gate", "deferredLabel:s;securityLabel:s", (i, v) => [Req("open-bugs", "open-bugs")], BugGate),
            new("skip-scan", "", (i, v) => [Req("skip-scan", "skip-scan")], SkipScan),
            new("file-exists", "path:s", (i, v) => [Req($"file:{Sub(S(i, "path"), v)}", "file", ("path", Sub(S(i, "path"), v)))], FileExists),
            new("file-regex", "path:s;pattern:s", (i, v) => [Req($"file-regex:{S(i, "path")}|{S(i, "pattern")}", "file-regex", ("path", S(i, "path")), ("pattern", S(i, "pattern")))], FileRegex),
            new("version-props", "", (i, v) => [Req("version-props", "version-props")], VersionProps),
            new("changelog-section", "fromMinor:s", (i, v) => [Req("changelog", "changelog"), Req("tags", "tags")], ChangelogSection),
            new("public-api-unshipped-empty", "", (i, v) => [Req("unshipped", "unshipped")], Unshipped),
            new("pages-freshness", "site:s;maxAgeDays:n", (i, v) => [Req($"pages:{S(i, "site")}", "pages", ("site", S(i, "site")))], PagesFreshness),
            new("coverage-flags-green", "", (i, v) => [Req("coverage-flags", "coverage-flags")], CoverageFlags),
            new("branch-protection", "contexts:s[]", (i, v) => [Req("branch-protection", "branch-protection")], BranchProtection),
            new("ci-result-needs", "", (i, v) => [Req("ci-result-needs", "ci-result-needs")], CiResultNeeds),
            new("spec-verified-date", "path:s;maxAgeDays:i", (i, v) => [Req($"spec-verified:{S(i, "path")}", "spec-verified", ("path", S(i, "path")))], SpecVerified),
            new("milestone-clean", "", (i, v) => [Req($"milestone:{v}", "milestone", ("version", v))], MilestoneClean),
            new("nuget-listing", "packageId:s;pattern:s", (i, v) => [Req($"nuget:{S(i, "packageId")}", "nuget", ("packageId", S(i, "packageId")))], NugetListing),
            new("release-asset", "namePattern:s;minCount:i", (i, v) => [Req($"release:v{v}", "release", ("tag", $"v{v}"))], ReleaseAsset),
            new("exclusive-dirs", "globs:s[]", (i, v) => [Req($"dirs:{string.Join('|', Ss(i, "globs"))}", "dirs", ("globs", string.Join('|', Ss(i, "globs"))))], ExclusiveDirs),
            new("alias", "item:s", (i, v) => [], (i, c) => Outcome.Fail("alias is resolved by the engine")),
        };
        return list.ToDictionary(d => d.Name, StringComparer.Ordinal);
    }

    public static string Core(string version)
    {
        var sv = SemVer.Parse(version)!.Value;
        return $"{sv.Major}.{sv.Minor}.{sv.Patch}";
    }

    static Outcome CiRun(Item i, EvalCtx c)
    {
        var wf = S(i, "workflow");
        var events = Ss(i, "events");
        var runs = J.Objs(c.Value($"ci-run:{wf}")?["runs"])
            .Where(r => J.Str(r["headSha"]) == c.Sha && J.Str(r["status"]) == "completed" && events.Contains(J.Str(r["event"]) ?? ""))
            .OrderByDescending(r => J.Str(r["createdAt"]), StringComparer.Ordinal).ToList();
        if (runs.Count == 0) return Outcome.Fail($"no completed {wf} run on {J.Short(c.Sha)} started by {string.Join(" or ", events)}");
        var run = runs[0];
        var id = J.Long(run["id"]);
        if (J.Str(run["conclusion"]) != "success") return Outcome.Fail($"run {id} concluded {J.Str(run["conclusion"])}");
        var jobs = J.Objs(run["jobs"]).ToList();
        if (jobs.Count == 0) return Outcome.Fail($"run {id} has no job records");
        var bad = jobs.Where(j => J.Str(j["conclusion"]) != "success").Select(j => J.Str(j["name"])).ToList();
        return bad.Count > 0 ? Outcome.Fail($"run {id}: {bad.Count} job(s) not success: {string.Join(", ", bad.Take(8))}")
            : Outcome.Pass($"run {id} ({J.Str(run["event"])}) succeeded, all {jobs.Count} jobs success");
    }

    static Outcome WorkflowLatest(Item i, EvalCtx c)
    {
        var wf = S(i, "workflow");
        var max = i.Params["maxAgeDays"]!.GetValue<double>();
        if (c.Value($"workflow-latest:{wf}")?["run"] is not JsonObject run) return Outcome.Fail($"no completed {wf} run on main");
        var updated = Time.Parse(J.Str(run["updatedAt"]) ?? "");
        if (updated is null) return Outcome.Fail($"run {J.Long(run["id"])} has no usable timestamp");
        var age = (c.Now - updated.Value).TotalDays;
        if (age > max) return Outcome.Fail($"latest {wf} run on main finished {J.Days(age)} days ago, window {max} days");
        return J.Str(run["conclusion"]) == "success"
            ? Outcome.Pass($"latest {wf} run on main succeeded {J.Days(age)} days ago (run {J.Long(run["id"])})")
            : Outcome.Fail($"latest {wf} run on main concluded {J.Str(run["conclusion"])} (run {J.Long(run["id"])})");
    }

    static int Rank(string? sev) => sev?.ToLowerInvariant() switch { "critical" => 4, "high" => 3, "medium" => 2, "moderate" => 2, "low" => 1, _ => 0 };

    static Outcome Alerts(EvalCtx c, string key, string min, string arrayName, string sevField)
    {
        if (c.Value(key)?[arrayName] is not JsonArray) return Outcome.Fail($"fact '{key}' has no '{arrayName}' list");
        var alerts = J.Objs(c.Value(key)?[arrayName]).ToList();
        var floor = Rank(min);
        // An alert whose severity is unknown counts as at or above the floor (fail closed).
        var hit = alerts.Count(a => Rank(J.Str(a[sevField])) is var r && (r >= floor || r == 0));
        var detail = string.Join(", ", new[] { "critical", "high", "medium", "low" }.Select(s => (s, n: alerts.Count(a => J.Str(a[sevField]) == s))).Where(x => x.n > 0).Select(x => $"{x.s} {x.n}"));
        return hit > 0 ? Outcome.Fail($"{hit} open alert(s) at {min} or higher ({detail})")
            : Outcome.Pass($"no open alerts at {min} or higher ({alerts.Count} open in total{(detail.Length > 0 ? ": " + detail : "")})");
    }

    static Outcome SecretAlerts(Item i, EvalCtx c)
    {
        if (c.Value("secret-scanning-alerts")?["alerts"] is not JsonArray) return Outcome.Fail("fact 'secret-scanning-alerts' has no 'alerts' list");
        var n = J.Objs(c.Value("secret-scanning-alerts")?["alerts"]).Count();
        return n > 0 ? Outcome.Fail($"{n} open secret-scanning alert(s)") : Outcome.Pass("no open secret-scanning alerts");
    }

    static Outcome Sonar(Item i, EvalCtx c)
    {
        var v = c.Value("sonar-issues");
        var high = J.Int(v?["high"]) ?? -1;
        var medium = J.Int(v?["medium"]) ?? 0;
        if (high < 0) return Outcome.Fail("sonar fact has no 'high' count");
        return high > 0 ? Outcome.Fail($"{high} open SonarCloud issue(s) at HIGH or BLOCKER ({medium} medium)")
            : Outcome.Pass($"no open SonarCloud issues at HIGH or BLOCKER ({medium} medium, listed in the evidence report)");
    }

    static Outcome IssueState(Item i, EvalCtx c)
    {
        var require = S(i, "require");
        var label = S(i, "label");
        var bad = new List<string>();
        foreach (var n in Is(i, "issues"))
        {
            var f = c.Value($"issue:{n}");
            var state = J.Str(f?["state"]);
            var hasLabel = J.Strs(f?["labels"]).Contains(label);
            var ok = require switch
            {
                "closed" => state == "closed",
                "open-with-label" => state == "open" && hasLabel,
                "closed-or-label" => state == "closed" || (state == "open" && hasLabel),
                _ => false,
            };
            if (!ok) bad.Add($"#{n} is {state}{(require != "closed" && !hasLabel ? $", no label {label}" : "")}");
        }
        var want = require == "closed" ? "closed" : require == "open-with-label" ? $"open and labelled {label}" : $"closed or labelled {label}";
        return bad.Count > 0 ? Outcome.Fail($"{bad.Count} issue(s) not {want}: {string.Join("; ", bad.Take(10))}")
            : Outcome.Pass($"all {Is(i, "issues").Length} issue(s) are {want}");
    }

    static Outcome BugGate(Item i, EvalCtx c)
    {
        var deferred = S(i, "deferredLabel");
        var security = S(i, "securityLabel");
        if (c.Value("open-bugs")?["issues"] is not JsonArray) return Outcome.Fail("fact 'open-bugs' has no 'issues' list");
        var issues = J.Objs(c.Value("open-bugs")?["issues"]).ToList();
        var bad = new List<string>();
        foreach (var b in issues)
        {
            var n = J.Int(b["number"]);
            var labels = J.Strs(b["labels"]).ToList();
            var title = J.Str(b["title"]) ?? "";
            if (labels.Contains(security) || Regex.IsMatch(title, @"(?i)\[[^\]]*security[^\]]*\]")) bad.Add($"#{n} is security-classified and cannot be deferred");
            else if (!labels.Contains(deferred)) bad.Add($"#{n} lacks the {deferred} label");
            else if ((J.Int(b["comments"]) ?? 0) < 1) bad.Add($"#{n} has {deferred} but no reason comment");
        }
        if (bad.Count > 0) return Outcome.Fail($"{bad.Count} of {issues.Count} open bug(s) block the release: {string.Join("; ", bad.Take(8))}");
        return Outcome.Pass(issues.Count == 0 ? "no open bug" : $"{issues.Count} open bug(s), all labelled {deferred} with a reason comment, none security-classified");
    }

    static Outcome SkipScan(Item i, EvalCtx c)
    {
        var v = c.Value("skip-scan");
        if (v?["unreferenced"] is not JsonArray || J.Int(v["total"]) is null) return Outcome.Fail("fact 'skip-scan' lacks 'total' or 'unreferenced'");
        var bad = J.Strs(v["unreferenced"]).ToList();
        return bad.Count > 0 ? Outcome.Fail($"{bad.Count} Skip= without an issue reference: {string.Join(", ", bad.Take(6))}")
            : Outcome.Pass($"all {J.Int(v?["total"])} Skip= occurrence(s) reference an issue");
    }

    // A path may carry the {version} token, replaced by the release version.
    static string Sub(string path, string version) => path.Replace("{version}", version, StringComparison.Ordinal);

    static Outcome FileExists(Item i, EvalCtx c)
    {
        var path = Sub(S(i, "path"), c.Version);
        return J.Bool(c.Value($"file:{path}")?["exists"]) == true ? Outcome.Pass($"{path} exists") : Outcome.Fail($"{path} does not exist");
    }

    static Outcome FileRegex(Item i, EvalCtx c)
    {
        var v = c.Value($"file-regex:{S(i, "path")}|{S(i, "pattern")}");
        if (J.Bool(v?["exists"]) != true) return Outcome.Fail($"{S(i, "path")} does not exist");
        return J.Bool(v?["matched"]) == true ? Outcome.Pass($"{S(i, "path")} matches /{S(i, "pattern")}/") : Outcome.Fail($"{S(i, "path")} does not match /{S(i, "pattern")}/");
    }

    static Outcome VersionProps(Item i, EvalCtx c)
    {
        var v = c.Value("version-props");
        var sv = SemVer.Parse(c.Version)!.Value;
        var prefix = J.Str(v?["prefix"]);
        var suffix = J.Str(v?["suffix"]) ?? "";
        if (prefix != Core(c.Version)) return Outcome.Fail($"VersionPrefix is '{prefix}', expected '{Core(c.Version)}'");
        return suffix == sv.Pre ? Outcome.Pass($"VersionPrefix {prefix}, VersionSuffix '{suffix}' match v{c.Version}")
            : Outcome.Fail($"VersionSuffix is '{suffix}', expected '{sv.Pre}' for v{c.Version}");
    }

    static Outcome ChangelogSection(Item i, EvalCtx c)
    {
        var sections = J.Objs(c.Value("changelog")?["sections"]).Select(s => (Version: J.Str(s["version"]) ?? "", Date: J.Str(s["date"]))).ToList();
        var own = sections.FirstOrDefault(s => s.Version == c.Version);
        if (own.Version is null or "") return Outcome.Fail($"CHANGELOG.md has no '## [{c.Version}]' section");
        if (own.Date is null) return Outcome.Fail($"the [{c.Version}] section has no date");
        var top = sections.FirstOrDefault(s => !s.Version.Equals("Unreleased", StringComparison.OrdinalIgnoreCase));
        if (top.Version != c.Version) return Outcome.Fail($"the top released section is [{top.Version}], expected [{c.Version}]");
        var from = SemVer.Parse(S(i, "fromMinor"))!.Value;
        var missing = new List<string>();
        foreach (var tag in J.Strs(c.Value("tags")?["names"]))
        {
            var m = Regex.Match(tag, @"^v(\d+)\.(\d+)\.0$");
            if (!m.Success || tag == $"v{c.Version}") continue;
            var (maj, min) = (int.Parse(m.Groups[1].Value), int.Parse(m.Groups[2].Value));
            if ((maj, min).CompareTo((from.Major, from.Minor)) < 0) continue;
            if (!sections.Any(s => s.Version == tag[1..] && s.Date is not null)) missing.Add(tag);
        }
        return missing.Count > 0 ? Outcome.Fail($"tag(s) without a dated CHANGELOG section: {string.Join(", ", missing)}")
            : Outcome.Pass($"[{c.Version}] is the top released section, dated {own.Date}; every earlier minor tag has a dated section");
    }

    static Outcome Unshipped(Item i, EvalCtx c)
    {
        if (c.Value("unshipped")?["nonEmpty"] is not JsonArray || J.Int(c.Value("unshipped")?["total"]) is null) return Outcome.Fail("fact 'unshipped' lacks 'total' or 'nonEmpty'");
        var bad = J.Strs(c.Value("unshipped")?["nonEmpty"]).ToList();
        return bad.Count > 0 ? Outcome.Fail($"{bad.Count} PublicAPI.Unshipped.txt file(s) not empty: {string.Join(", ", bad.Take(4))}")
            : Outcome.Pass($"all {J.Int(c.Value("unshipped")?["total"])} PublicAPI.Unshipped.txt files are empty");
    }

    static Outcome PagesFreshness(Item i, EvalCtx c)
    {
        var site = S(i, "site");
        var max = i.Params["maxAgeDays"]!.GetValue<double>();
        var raw = J.Str(c.Value($"pages:{site}")?["timestamp"]);
        var t = raw is null ? null : Time.Parse(raw);
        if (t is null) return Outcome.Fail($"{site} data has no usable timestamp");
        if (t.Value - c.Now > TimeSpan.FromHours(1)) return Outcome.Fail($"{site} timestamp {raw} is in the future");
        var age = (c.Now - t.Value).TotalDays;
        return age > max ? Outcome.Fail($"{site} data is {J.Days(age)} days old (published {Time.Format(t.Value)}), window {max} days")
            : Outcome.Pass($"{site} data published {Time.Format(t.Value)}, {J.Days(age)} days old (window {max} days)");
    }

    static Outcome CoverageFlags(Item i, EvalCtx c)
    {
        var v = c.Value("coverage-flags");
        var failing = J.Objs(v?["failing"]).ToList();
        var packages = J.Int(v?["packages"]) ?? 0;
        if (packages == 0) return Outcome.Fail("the coverage data lists no package with per-flag targets");
        if (failing.Count == 0) return Outcome.Pass($"all {packages} package(s) meet every per-flag target in the published data");
        var sample = string.Join("; ", failing.Take(3).Select(f => $"{J.Str(f["package"])} {J.Str(f["flag"])} {J.Str(f["coverage"])}<{J.Str(f["target"])}"));
        return Outcome.Fail($"{failing.Count} package/flag pair(s) below target in {packages} package(s), e.g. {sample}");
    }

    static Outcome BranchProtection(Item i, EvalCtx c)
    {
        var p = c.Value("branch-protection")?["protection"] as JsonObject;
        if (p is null) return Outcome.Fail("no protection data");
        var bad = new List<string>();
        if (J.Bool(p["enforce_admins"]?["enabled"]) != true) bad.Add("enforce_admins is not true");
        if (J.Int(p["required_pull_request_reviews"]?["required_approving_review_count"]) != 0) bad.Add("required_approving_review_count is not 0");
        if (J.Bool(p["required_conversation_resolution"]?["enabled"]) != true) bad.Add("required_conversation_resolution is not true");
        if (J.Bool(p["required_linear_history"]?["enabled"]) != true) bad.Add("required_linear_history is not true");
        var actual = J.Strs(p["required_status_checks"]?["contexts"]).Concat(J.Objs(p["required_status_checks"]?["checks"]).Select(x => J.Str(x["context"]) ?? "")).ToHashSet(StringComparer.Ordinal);
        var expected = Ss(i, "contexts");
        if (!actual.SetEquals(expected)) bad.Add($"required contexts are [{string.Join(", ", actual.OrderBy(x => x, StringComparer.Ordinal))}], expected exactly [{string.Join(", ", expected)}]");
        return bad.Count > 0 ? Outcome.Fail(string.Join("; ", bad)) : Outcome.Pass($"main protection matches SPEC-000 AC-020 field by field; contexts exactly {string.Join(", ", expected)}");
    }

    static Outcome CiResultNeeds(Item i, EvalCtx c)
    {
        var v = c.Value("ci-result-needs");
        var needs = J.Strs(v?["needs"]).ToHashSet(StringComparer.Ordinal);
        var required = J.Strs(v?["testJobs"]).Append("build").ToList();
        var missing = required.Where(r => !needs.Contains(r)).ToList();
        if (missing.Count > 0) return Outcome.Fail($"ci-result does not need: {string.Join(", ", missing)}");
        return J.Bool(v?["ifAlways"]) == true ? Outcome.Pass($"ci-result needs build and all {required.Count - 1} test-* job(s) with if: always()") : Outcome.Fail("ci-result lacks if: always()");
    }

    static Outcome SpecVerified(Item i, EvalCtx c)
    {
        var raw = J.Str(c.Value($"spec-verified:{S(i, "path")}")?["date"]);
        if (raw is null || !DateTime.TryParseExact(raw, "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out var date))
            return Outcome.Fail($"{S(i, "path")} has no 'Verified on **yyyy-MM-dd**' line");
        var max = i.Params["maxAgeDays"]!.GetValue<int>();
        var days = (c.Now.UtcDateTime.Date - date).Days;
        if (days < 0) return Outcome.Fail($"verification date {raw} is in the future");
        return days > max ? Outcome.Fail($"verified on {raw}, {days} days before the evaluation, limit {max} days")
            : Outcome.Pass($"verified on {raw}, {days} days before the evaluation (limit {max} days)");
    }

    static Outcome MilestoneClean(Item i, EvalCtx c)
    {
        var v = c.Value($"milestone:{c.Version}");
        if (v?["milestone"] is not JsonObject m) return Outcome.Fail($"no milestone whose title starts with v{c.Version}");
        var open = J.Objs(v["open"]).Select(o => J.Int(o["number"]) ?? 0).Where(n => !c.Signoff.AllowOpen.Contains(n)).ToList();
        return open.Count > 0 ? Outcome.Fail($"{open.Count} open issue(s) in milestone '{J.Str(m["title"])}' outside the sign-off allow-list: {string.Join(", ", open.Take(10).Select(n => "#" + n))}")
            : Outcome.Pass($"milestone '{J.Str(m["title"])}' has no open issue outside the sign-off allow-list");
    }

    static Outcome NugetListing(Item i, EvalCtx c)
    {
        var rx = new Regex(S(i, "pattern").Replace("{version}", Regex.Escape(c.Version), StringComparison.Ordinal), RegexOptions.CultureInvariant);
        var hits = J.Strs(c.Value($"nuget:{S(i, "packageId")}")?["versions"]).Where(v => rx.IsMatch(v)).ToList();
        return hits.Count > 0 ? Outcome.Pass($"{S(i, "packageId")} is listed on nuget.org: {string.Join(", ", hits.Take(3))}")
            : Outcome.Fail($"{S(i, "packageId")} has no version on nuget.org matching /{rx}/");
    }

    static Outcome ReleaseAsset(Item i, EvalCtx c)
    {
        var v = c.Value($"release:v{c.Version}");
        if (J.Bool(v?["exists"]) != true) return Outcome.Fail($"no GitHub Release for tag v{c.Version}");
        var rx = new Regex(S(i, "namePattern"), RegexOptions.CultureInvariant);
        var hits = J.Strs(v?["assets"]).Count(a => rx.IsMatch(a));
        var min = i.Params["minCount"]!.GetValue<int>();
        return hits >= min ? Outcome.Pass($"release v{c.Version} exists with {hits} matching asset(s) (needs {min})") : Outcome.Fail($"release v{c.Version} has {hits} asset(s) matching /{rx}/, needs {min}");
    }

    static Outcome ExclusiveDirs(Item i, EvalCtx c)
    {
        var counts = c.Value($"dirs:{string.Join('|', Ss(i, "globs"))}")?["counts"] as JsonObject;
        var present = Ss(i, "globs").Where(g => (J.Int(counts?[g]) ?? 0) > 0).ToList();
        return present.Count > 1 ? Outcome.Fail($"more than one family exists: {string.Join(", ", present)}") : Outcome.Pass(present.Count == 1 ? $"only {present[0]} exists" : "none of the families exists");
    }
}

// =============================================================================================
// Engine: severity, fail-closed fact checks, attestation fallback, alias items
// =============================================================================================

sealed record ItemResult(Item Item, string Status, string Reason, IReadOnlyList<string> FactKeys);

sealed record EvalRun(string Version, string Profile, IReadOnlyList<ItemResult> Results)
{
    public int Count(string status) => Results.Count(r => r.Status == status);
    public bool Passed => Count("FAIL") == 0 && Count("PENDING") == 0;
}

static class Engine
{
    public static EvalRun Run(Registry reg, EvalCtx c, HashSet<string>? only)
    {
        var memo = new Dictionary<string, (Outcome, IReadOnlyList<string>)>(StringComparer.Ordinal);
        var results = new List<ItemResult>();
        foreach (var item in reg.Items.Where(i => !i.IsRetired && (only is null || only.Contains(i.Id))))
        {
            var sev = item.SeverityFor(c.Profile);
            if (sev == "skip") { results.Add(new ItemResult(item, "SKIP", $"profile {c.Profile} skips this item", [])); continue; }
            var (o, keys) = Raw(item, reg, c, memo);
            results.Add(new ItemResult(item, Map(o.Kind, sev), o.Reason, keys));
        }
        return new EvalRun(c.Version, c.Profile, results);
    }

    static string Map(OutcomeKind kind, string sev) => kind switch
    {
        OutcomeKind.Pass => "PASS",
        OutcomeKind.NotNeeded => "SKIP",
        OutcomeKind.Fail => sev == "block" ? "FAIL" : "WARN",
        _ => sev == "block" ? "PENDING" : "WARN",
    };

    static (Outcome, IReadOnlyList<string>) Raw(Item item, Registry reg, EvalCtx c, Dictionary<string, (Outcome, IReadOnlyList<string>)> memo)
    {
        if (memo.TryGetValue(item.Id, out var cached)) return cached;
        var r = item.Kind == "manual" ? Manual(item, reg, c) : item.CheckName == "alias" ? Alias(item, reg, c, memo) : Auto(item, reg, c);
        memo[item.Id] = r;
        return r;
    }

    static (Outcome, IReadOnlyList<string>) Alias(Item item, Registry reg, EvalCtx c, Dictionary<string, (Outcome, IReadOnlyList<string>)> memo)
    {
        var targetId = J.Str(item.Params["item"])!;
        var target = reg.Items.First(i => i.Id == targetId);
        var (o, keys) = Raw(target, reg, c, memo);
        return (o with { Reason = $"same fact as {targetId}: {o.Reason}" }, keys);
    }

    static (Outcome, IReadOnlyList<string>) Manual(Item item, Registry reg, EvalCtx c)
    {
        if (item.Attests is not null) return (Attestation(item, reg, c), []);
        if (!c.Signoff.Items.TryGetValue(item.Id, out var a)) return (Outcome.Pending("not answered: tick its line in the sign-off file and add 'evidence: <link>'"), []);
        if (!a.Ticked) return (Outcome.Pending("unticked in the sign-off file"), []);
        return a.Evidence is null ? (Outcome.Pending("ticked without an evidence link, which counts as unanswered"), []) : (Outcome.Pass($"answered, evidence: {a.Evidence}"), []);
    }

    static Outcome Attestation(Item item, Registry reg, EvalCtx c)
    {
        var target = reg.Items.First(i => i.Id == item.Attests);
        var (bad, _) = FactProblems(target, c);
        if (bad is null) return Outcome.NotNeeded($"not needed: the automatic fact for {target.Id} was collected");
        var ev = c.Signoff.EvidenceOf(item.Id);
        return ev is not null ? Outcome.Pass($"accepted because the automatic fact for {target.Id} has an error; this attestation replaces it, evidence: {ev}")
            : Outcome.Pending($"the automatic fact for {target.Id} has an error; answer this attestation with an evidence link or fix the collection");
    }

    static (string? Problem, List<string> Keys) FactProblems(Item item, EvalCtx c)
    {
        var def = Evaluators.Table[item.CheckName!];
        var keys = def.Needs(item, c.Version).Select(r => r.Key).ToList();
        foreach (var k in keys)
        {
            if (!c.Facts.Facts.TryGetValue(k, out var f)) return ($"fact '{k}' is missing from facts.json", keys);
            if (f.Error is not null) return ($"fact '{k}' could not be collected: {f.Error}", keys);
            if (f.Value is null) return ($"fact '{k}' has neither a value nor an error", keys);
        }
        return (null, keys);
    }

    static (Outcome, IReadOnlyList<string>) Auto(Item item, Registry reg, EvalCtx c)
    {
        var (problem, keys) = FactProblems(item, c);
        if (problem is not null)
        {
            var attest = reg.Items.FirstOrDefault(i => !i.IsRetired && i.Attests == item.Id && i.SeverityFor(c.Profile) != "skip");
            if (attest is not null && c.Signoff.EvidenceOf(attest.Id) is { } ev)
                return (Outcome.Pass($"ATTESTED: {attest.Id} replaced the automatic fact (evidence: {ev}); {problem}"), keys);
            return (Outcome.Fail(problem), keys);
        }
        try { return (Evaluators.Table[item.CheckName!].Eval(item, c), keys); }
        catch (Exception ex) when (ex is not OutOfMemoryException) { return (Outcome.Fail($"evaluator error ({ex.GetType().Name}); failing closed"), keys); }
    }
}

// =============================================================================================
// Remote access: gh api (REST only) and HttpClient behind one retry helper
// =============================================================================================

sealed record Response(int Status, string Body, IReadOnlyDictionary<string, string> Headers, string? Failure)
{
    public bool Ok => Failure is null && Status is >= 200 and < 300;
}

interface IRemote
{
    Task<Response> GhAsync(string endpoint, string? token);
    Task<Response> HttpAsync(string url);
}

sealed record ProcResult(int Code, string Stdout, string Stderr);

static class Proc
{
    public static async Task<ProcResult> RunAsync(string file, IEnumerable<string> args, IDictionary<string, string>? env)
    {
        var psi = new ProcessStartInfo(file) { RedirectStandardOutput = true, RedirectStandardError = true, UseShellExecute = false, StandardOutputEncoding = Encoding.UTF8 };
        foreach (var a in args) psi.ArgumentList.Add(a);
        if (env is not null) foreach (var (k, v) in env) psi.Environment[k] = v;
        using var p = Process.Start(psi) ?? throw new InvalidOperationException($"could not start {file}");
        var stdout = p.StandardOutput.ReadToEndAsync();
        var stderr = p.StandardError.ReadToEndAsync();
        await p.WaitForExitAsync();
        return new ProcResult(p.ExitCode, await stdout, await stderr);
    }
}

sealed class RealRemote : IRemote
{
    static readonly HttpClient Http = CreateClient();

    static HttpClient CreateClient()
    {
        var c = new HttpClient { Timeout = TimeSpan.FromSeconds(30) };
        c.DefaultRequestHeaders.UserAgent.ParseAdd("Encina-ReleaseReadiness/1.0");
        return c;
    }

    public async Task<Response> GhAsync(string endpoint, string? token)
    {
        try
        {
            var env = token is null ? null : new Dictionary<string, string> { ["GH_TOKEN"] = token, ["GITHUB_TOKEN"] = token };
            var r = await Proc.RunAsync("gh", ["api", "--include", "-H", "Accept: application/vnd.github+json", "-H", "X-GitHub-Api-Version: 2022-11-28", endpoint], env);
            return ParseInclude(r);
        }
        catch (Exception ex) when (ex is InvalidOperationException or System.ComponentModel.Win32Exception)
        {
            return new Response(0, "", new Dictionary<string, string>(), $"gh could not run ({ex.GetType().Name})");
        }
    }

    static Response ParseInclude(ProcResult r)
    {
        var text = r.Stdout.Replace("\r\n", "\n", StringComparison.Ordinal);
        if (!text.StartsWith("HTTP/", StringComparison.Ordinal))
            return new Response(0, "", new Dictionary<string, string>(), FirstLine(r.Stderr) ?? "gh produced no HTTP response");
        var split = text.IndexOf("\n\n", StringComparison.Ordinal);
        var head = (split < 0 ? text : text[..split]).Split('\n');
        var body = split < 0 ? "" : text[(split + 2)..];
        var status = int.Parse(head[0].Split(' ')[1]);
        var headers = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        foreach (var line in head.Skip(1))
        {
            var idx = line.IndexOf(':', StringComparison.Ordinal);
            if (idx > 0) headers[line[..idx].Trim()] = line[(idx + 1)..].Trim();
        }
        return new Response(status, body, headers, null);
    }

    static string? FirstLine(string s) => s.Split('\n').Select(l => l.Trim()).FirstOrDefault(l => l.Length > 0);

    public async Task<Response> HttpAsync(string url)
    {
        try
        {
            using var resp = await Http.GetAsync(new Uri(url));
            var headers = resp.Headers.Concat(resp.Content.Headers).ToDictionary(h => h.Key, h => string.Join(",", h.Value), StringComparer.OrdinalIgnoreCase);
            return new Response((int)resp.StatusCode, await resp.Content.ReadAsStringAsync(), headers, null);
        }
        catch (Exception ex) when (ex is HttpRequestException or TaskCanceledException)
        {
            return new Response(0, "", new Dictionary<string, string>(), ex is TaskCanceledException ? "timed out" : "request failed");
        }
    }

    public static async Task<string> IdentityAsync()
    {
        var r = await new RealRemote().GhAsync("user", null);
        return r.Ok && J.Str(JsonNode.Parse(r.Body)?["login"]) is { } login ? login : "unknown";
    }
}

sealed class CollectException(string message, string? source = null) : Exception(message)
{
    public string? FactSource { get; } = source;
}

sealed record CollectCtx(Env Env, string Repo, string Root, string Version, string Profile, string Sha, string? AppToken);

// One retry helper for every remote call: 3 attempts, exponential backoff, Retry-After and
// x-ratelimit-reset honoured. The attempt count is recorded in the fact.
sealed class Fetcher(CollectCtx c)
{
    public const int MaxAttempts = 3;
    public int Attempts { get; private set; }

    public async Task<Response> GetAsync(Func<Task<Response>> call)
    {
        Response last = null!;
        for (var attempt = 1; attempt <= MaxAttempts; attempt++)
        {
            Attempts++;
            last = await call();
            if (!IsTransient(last) || attempt == MaxAttempts) return last;
            await c.Env.Delay(Backoff(last, attempt, c.Env.Clock.GetUtcNow()));
        }
        return last;
    }

    public static bool IsTransient(Response r) =>
        r.Failure is not null || r.Status >= 500 || r.Status == 429
        || (r.Status == 403 && (r.Headers.GetValueOrDefault("x-ratelimit-remaining") == "0" || r.Headers.ContainsKey("retry-after") || r.Body.Contains("rate limit", StringComparison.OrdinalIgnoreCase)));

    public static TimeSpan Backoff(Response r, int attempt, DateTimeOffset now)
    {
        var cap = TimeSpan.FromSeconds(60);
        if (r.Headers.TryGetValue("retry-after", out var ra) && double.TryParse(ra, NumberStyles.Float, CultureInfo.InvariantCulture, out var secs))
            return TimeSpan.FromSeconds(Math.Clamp(secs, 0, cap.TotalSeconds));
        if (r.Headers.GetValueOrDefault("x-ratelimit-remaining") == "0" && r.Headers.TryGetValue("x-ratelimit-reset", out var reset)
            && long.TryParse(reset, NumberStyles.Integer, CultureInfo.InvariantCulture, out var epoch))
            return TimeSpan.FromSeconds(Math.Clamp((DateTimeOffset.FromUnixTimeSeconds(epoch) - now).TotalSeconds, 1, cap.TotalSeconds));
        return TimeSpan.FromSeconds(Math.Min(Math.Pow(2, attempt - 1), cap.TotalSeconds));
    }

    public static string GhUrl(string endpoint) => $"https://api.github.com/{endpoint}";

    // Parsed JSON of a GET. A 404 returns null when allowNotFound; any other failure throws (fail closed).
    public async Task<JsonNode?> JsonAsync(string endpoint, string? token = null, bool allowNotFound = false)
    {
        var r = await GetAsync(() => c.Env.Remote.GhAsync(endpoint, token));
        return Parse(r, GhUrl(endpoint), allowNotFound);
    }

    public async Task<JsonNode?> HttpJsonAsync(string url, bool allowNotFound = false) =>
        Parse(await GetAsync(() => c.Env.Remote.HttpAsync(url)), url, allowNotFound);

    static JsonNode? Parse(Response r, string url, bool allowNotFound)
    {
        if (r.Failure is not null) throw new CollectException($"GET {url} failed: {r.Failure}", url);
        if (r.Status == 404 && allowNotFound) return null;
        if (!r.Ok) throw new CollectException($"GET {url} returned HTTP {r.Status}", url);
        try { return JsonNode.Parse(r.Body); }
        catch (JsonException) { throw new CollectException($"GET {url} returned a body that is not JSON", url); }
    }

    public async Task<JsonArray> PagedAsync(string endpoint, string? token = null, string? arrayProperty = null, int maxPages = 30)
    {
        var all = new JsonArray();
        for (var page = 1; page <= maxPages; page++)
        {
            var node = await JsonAsync($"{endpoint}{(endpoint.Contains('?') ? '&' : '?')}per_page=100&page={page}", token);
            var arr = (arrayProperty is null ? node : node?[arrayProperty]) as JsonArray ?? throw new CollectException($"GET {GhUrl(endpoint)} did not return a list", GhUrl(endpoint));
            foreach (var x in arr) all.Add(x?.DeepClone());
            if (arr.Count < 100) return all;
        }
        throw new CollectException($"GET {GhUrl(endpoint)} has more than {maxPages} pages; refusing a truncated list", GhUrl(endpoint));
    }
}

// =============================================================================================
// Collectors: each answers one fact. A failed fact is recorded with its error, never omitted.
// =============================================================================================

static class Collectors
{
    const string SonarProject = "dlrivada_Encina";

    public static async Task<SortedDictionary<string, Fact>> CollectAsync(Registry reg, CollectCtx c)
    {
        var requests = new SortedDictionary<string, FactRequest>(StringComparer.Ordinal);
        foreach (var item in reg.Items.Where(i => !i.IsRetired && i.Kind != "manual" && i.SeverityFor(c.Profile) != "skip"))
            foreach (var r in Evaluators.Table[item.CheckName!].Needs(item, c.Version)) requests.TryAdd(r.Key, r);
        // An alias reads its target's facts; the target is active whenever the alias is (checked by --check-registry).
        var facts = new SortedDictionary<string, Fact>(StringComparer.Ordinal);
        foreach (var (key, req) in requests) facts[key] = await OneAsync(req, c);
        return facts;
    }

    public static async Task<Fact> OneAsync(FactRequest req, CollectCtx c)
    {
        var f = new Fetcher(c);
        string source = "";
        try
        {
            var (value, src) = await DispatchAsync(req, c, f);
            return new Fact(value, src, Time.Format(c.Env.Clock.GetUtcNow()), null, f.Attempts);
        }
        catch (CollectException ex)
        {
            return new Fact(null, ex.FactSource ?? source, Time.Format(c.Env.Clock.GetUtcNow()), ex.Message, f.Attempts);
        }
        catch (Exception ex) when (ex is IOException or JsonException or InvalidOperationException or FormatException or UnauthorizedAccessException or ArgumentException)
        {
            // Only the exception type is recorded: a message may carry content that must not reach an artifact.
            return new Fact(null, source, Time.Format(c.Env.Clock.GetUtcNow()), $"collector failed ({ex.GetType().Name})", f.Attempts);
        }
    }

    static string A(FactRequest r, string name) => J.Str(r.Args[name]) ?? throw new CollectException($"collector argument '{name}' is missing");

    static async Task<(JsonNode, string)> DispatchAsync(FactRequest r, CollectCtx c, Fetcher f) => r.Collector switch
    {
        "ci-run" => await CiRun(c, f, A(r, "workflow")),
        "workflow-latest" => await WorkflowLatest(c, f, A(r, "workflow")),
        "code-scanning" => await CodeScanning(c, f),
        "secret-scanning" => await SecretScanning(c, f),
        "dependabot" => await Dependabot(c, f),
        "sonar" => await Sonar(f),
        "issue" => await IssueFact(c, f, A(r, "number")),
        "open-bugs" => await OpenBugs(c, f),
        "tags" => await Tags(c, f),
        "milestone" => await Milestone(c, f, A(r, "version")),
        "branch-protection" => await BranchProtection(c, f),
        "nuget" => await Nuget(f, A(r, "packageId")),
        "release" => await Release(c, f, A(r, "tag")),
        "pages" => await Pages(c, f, A(r, "site")),
        "coverage-flags" => await CoverageFlags(c, f),
        _ => Local(r, c),
    };

    // ---- GitHub ----

    static async Task<(JsonNode, string)> CiRun(CollectCtx c, Fetcher f, string workflow)
    {
        var endpoint = $"repos/{c.Repo}/actions/workflows/{workflow}/runs?head_sha={c.Sha}&per_page=20";
        var data = await f.JsonAsync(endpoint);
        var runs = new JsonArray();
        foreach (var run in J.Objs(data?["workflow_runs"]).Take(5))
        {
            var id = J.Long(run["id"]);
            var jobsNode = await f.JsonAsync($"repos/{c.Repo}/actions/runs/{id}/jobs?per_page=100");
            var jobs = new JsonArray();
            foreach (var j in J.Objs(jobsNode?["jobs"])) jobs.Add(new JsonObject { ["name"] = J.Str(j["name"]), ["conclusion"] = J.Str(j["conclusion"]) });
            if ((J.Int(jobsNode?["total_count"]) ?? 0) > jobs.Count) throw new CollectException($"run {id} has more jobs than one page; refusing a truncated list", Fetcher.GhUrl(endpoint));
            runs.Add(new JsonObject
            {
                ["id"] = id, ["event"] = J.Str(run["event"]), ["status"] = J.Str(run["status"]), ["conclusion"] = J.Str(run["conclusion"]),
                ["headSha"] = J.Str(run["head_sha"]), ["url"] = J.Str(run["html_url"]), ["createdAt"] = J.Str(run["created_at"]), ["jobs"] = jobs,
            });
        }
        return (new JsonObject { ["runs"] = runs }, Fetcher.GhUrl(endpoint));
    }

    static async Task<(JsonNode, string)> WorkflowLatest(CollectCtx c, Fetcher f, string workflow)
    {
        var endpoint = $"repos/{c.Repo}/actions/workflows/{workflow}/runs?branch=main&status=completed&per_page=1";
        var first = J.Objs((await f.JsonAsync(endpoint))?["workflow_runs"]).FirstOrDefault();
        JsonNode? run = first is null ? null : new JsonObject
        {
            ["id"] = J.Long(first["id"]), ["event"] = J.Str(first["event"]), ["conclusion"] = J.Str(first["conclusion"]),
            ["updatedAt"] = J.Str(first["updated_at"]), ["headSha"] = J.Str(first["head_sha"]), ["url"] = J.Str(first["html_url"]),
        };
        return (new JsonObject { ["run"] = run }, Fetcher.GhUrl(endpoint));
    }

    // Severity: security_severity_level when the rule has one, else the rule severity (error=high, warning=medium, note=low).
    static async Task<(JsonNode, string)> CodeScanning(CollectCtx c, Fetcher f)
    {
        var endpoint = $"repos/{c.Repo}/code-scanning/alerts?state=open";
        var alerts = new JsonArray();
        foreach (var a in J.Objs(await f.PagedAsync(endpoint)))
        {
            var rule = a["rule"] as JsonObject;
            var sev = J.Str(rule?["security_severity_level"]) ?? J.Str(rule?["severity"]) switch { "error" => "high", "warning" => "medium", "note" => "low", { } s => s, _ => "unknown" };
            alerts.Add(new JsonObject { ["number"] = J.Int(a["number"]), ["severity"] = sev, ["rule"] = J.Str(rule?["id"]), ["url"] = J.Str(a["html_url"]) });
        }
        return (new JsonObject { ["alerts"] = alerts }, Fetcher.GhUrl(endpoint));
    }

    static string RequireToken(CollectCtx c) =>
        string.IsNullOrEmpty(c.AppToken) ? throw new CollectException($"{Cli.AppTokenVariable} is not set; the GitHub App token is required for this fact") : c.AppToken;

    static async Task<(JsonNode, string)> SecretScanning(CollectCtx c, Fetcher f)
    {
        var token = RequireToken(c);
        var endpoint = $"repos/{c.Repo}/secret-scanning/alerts?state=open";
        var alerts = new JsonArray();
        foreach (var a in J.Objs(await f.PagedAsync(endpoint, token)))
            // Only the existence of an open alert is kept: facts.json is committed to a public repository.
            alerts.Add(new JsonObject { ["state"] = "open" });
        return (new JsonObject { ["alerts"] = alerts }, Fetcher.GhUrl(endpoint));
    }

    static async Task<(JsonNode, string)> Dependabot(CollectCtx c, Fetcher f)
    {
        var token = RequireToken(c);
        var endpoint = $"repos/{c.Repo}/dependabot/alerts?state=open";
        var alerts = new JsonArray();
        foreach (var a in J.Objs(await f.PagedAsync(endpoint, token)))
            // Severity only: Dependabot alert details are not public and facts.json is committed.
            alerts.Add(new JsonObject { ["severity"] = J.Str(a["security_advisory"]?["severity"]) ?? "unknown" });
        return (new JsonObject { ["alerts"] = alerts }, Fetcher.GhUrl(endpoint));
    }

    static async Task<(JsonNode, string)> IssueFact(CollectCtx c, Fetcher f, string number)
    {
        var endpoint = $"repos/{c.Repo}/issues/{number}";
        var i = await f.JsonAsync(endpoint) as JsonObject ?? throw new CollectException($"issue {number} not found", Fetcher.GhUrl(endpoint));
        return (new JsonObject
        {
            ["number"] = J.Int(i["number"]), ["state"] = J.Str(i["state"]), ["title"] = J.Str(i["title"]),
            ["labels"] = new JsonArray(J.Objs(i["labels"]).Select(l => (JsonNode?)JsonValue.Create(J.Str(l["name"]))).ToArray()),
        }, $"https://github.com/{c.Repo}/issues/{number}");
    }

    static async Task<(JsonNode, string)> OpenBugs(CollectCtx c, Fetcher f)
    {
        var endpoint = $"repos/{c.Repo}/issues?state=open";
        var bugs = new JsonArray();
        foreach (var i in J.Objs(await f.PagedAsync(endpoint)).Where(i => i["pull_request"] is null))
        {
            var labels = J.Objs(i["labels"]).Select(l => J.Str(l["name"]) ?? "").ToList();
            var title = J.Str(i["title"]) ?? "";
            if (!labels.Contains("bug") && !title.StartsWith("[BUG]", StringComparison.OrdinalIgnoreCase)) continue;
            bugs.Add(new JsonObject
            {
                ["number"] = J.Int(i["number"]), ["title"] = title, ["comments"] = J.Int(i["comments"]),
                ["labels"] = new JsonArray(labels.Select(l => (JsonNode?)JsonValue.Create(l)).ToArray()),
            });
        }
        return (new JsonObject { ["issues"] = bugs }, Fetcher.GhUrl(endpoint));
    }

    static async Task<(JsonNode, string)> Tags(CollectCtx c, Fetcher f)
    {
        var endpoint = $"repos/{c.Repo}/tags";
        var names = new JsonArray(J.Objs(await f.PagedAsync(endpoint)).Select(t => (JsonNode?)JsonValue.Create(J.Str(t["name"]))).ToArray());
        return (new JsonObject { ["names"] = names }, Fetcher.GhUrl(endpoint));
    }

    // The milestone whose title starts with v<version> and is not a longer version (v1.0.0 must not match v1.0.0-rc.1).
    static async Task<(JsonNode, string)> Milestone(CollectCtx c, Fetcher f, string version)
    {
        var endpoint = $"repos/{c.Repo}/milestones?state=all";
        var rx = new Regex($"^v{Regex.Escape(version)}(?![\\d.\\-])", RegexOptions.CultureInvariant);
        var found = J.Objs(await f.PagedAsync(endpoint)).FirstOrDefault(m => rx.IsMatch(J.Str(m["title"]) ?? ""));
        if (found is null) return (new JsonObject { ["milestone"] = null, ["open"] = new JsonArray() }, Fetcher.GhUrl(endpoint));
        var number = J.Int(found["number"]);
        var open = new JsonArray();
        foreach (var i in J.Objs(await f.PagedAsync($"repos/{c.Repo}/issues?milestone={number}&state=open")).Where(i => i["pull_request"] is null))
            open.Add(new JsonObject { ["number"] = J.Int(i["number"]), ["title"] = J.Str(i["title"]) });
        return (new JsonObject { ["milestone"] = new JsonObject { ["number"] = number, ["title"] = J.Str(found["title"]) }, ["open"] = open }, $"https://github.com/{c.Repo}/milestone/{number}");
    }

    static async Task<(JsonNode, string)> BranchProtection(CollectCtx c, Fetcher f)
    {
        const string remedy = "add \"Administration: Read-only\" to the encina-release-gate GitHub App and accept the updated permission on the installation (docs/releases/RELEASE-PROCESS.md, \"Set up the GitHub App\")";
        var endpoint = $"repos/{c.Repo}/branches/main/protection";
        if (string.IsNullOrEmpty(c.AppToken)) throw new CollectException($"{Cli.AppTokenVariable} is not set; branch protection needs the App token. To fix: {remedy}", Fetcher.GhUrl(endpoint));
        JsonNode? p;
        try { p = await f.JsonAsync(endpoint, c.AppToken); }
        catch (CollectException ex) { throw new CollectException($"{ex.Message}. To fix: {remedy}", Fetcher.GhUrl(endpoint)); }
        if (p is null) throw new CollectException($"main has no branch protection. To fix: {remedy}", Fetcher.GhUrl(endpoint));
        // Only the fields SPEC-000 AC-020 needs are kept.
        var kept = new JsonObject();
        foreach (var key in new[] { "enforce_admins", "required_pull_request_reviews", "required_conversation_resolution", "required_linear_history" })
            kept[key] = p[key] is JsonObject o ? new JsonObject { ["enabled"] = o["enabled"]?.DeepClone(), ["required_approving_review_count"] = o["required_approving_review_count"]?.DeepClone() } : null;
        kept["required_status_checks"] = p["required_status_checks"] is JsonObject rs
            ? new JsonObject { ["contexts"] = rs["contexts"]?.DeepClone(), ["checks"] = new JsonArray(J.Objs(rs["checks"]).Select(x => (JsonNode?)new JsonObject { ["context"] = J.Str(x["context"]) }).ToArray()) }
            : null;
        return (new JsonObject { ["protection"] = kept }, Fetcher.GhUrl(endpoint));
    }

    static async Task<(JsonNode, string)> Release(CollectCtx c, Fetcher f, string tag)
    {
        var endpoint = $"repos/{c.Repo}/releases/tags/{tag}";
        var r = await f.JsonAsync(endpoint, null, true);
        var assets = new JsonArray(J.Objs(r?["assets"]).Select(a => (JsonNode?)JsonValue.Create(J.Str(a["name"]))).ToArray());
        return (new JsonObject { ["exists"] = r is not null, ["assets"] = assets }, Fetcher.GhUrl(endpoint));
    }

    // ---- Public endpoints ----

    static async Task<(JsonNode, string)> Sonar(Fetcher f)
    {
        var b = $"https://sonarcloud.io/api/issues/search?componentKeys={SonarProject}&resolved=false";
        var high = await f.HttpJsonAsync($"{b}&impactSeverities=BLOCKER,HIGH&ps=1");
        var medium = await f.HttpJsonAsync($"{b}&impactSeverities=MEDIUM&ps=100");
        var list = new JsonArray();
        foreach (var i in J.Objs(medium?["issues"]))
            list.Add(new JsonObject { ["key"] = J.Str(i["key"]), ["rule"] = J.Str(i["rule"]), ["component"] = (J.Str(i["component"]) ?? "").Replace($"{SonarProject}:", "", StringComparison.Ordinal) });
        var high1 = J.Int(high?["total"]) ?? throw new CollectException("SonarCloud answer has no total", $"{b}&impactSeverities=BLOCKER,HIGH&ps=1");
        return (new JsonObject { ["high"] = high1, ["medium"] = J.Int(medium?["total"]) ?? 0, ["mediumIssues"] = list },
            $"https://sonarcloud.io/project/issues?id={SonarProject}&resolved=false");
    }

    static async Task<(JsonNode, string)> Nuget(Fetcher f, string packageId)
    {
        var url = $"https://api.nuget.org/v3-flatcontainer/{packageId.ToLowerInvariant()}/index.json";
        var r = await f.HttpJsonAsync(url, true);
        var versions = new JsonArray(J.Strs(r?["versions"]).Select(v => (JsonNode?)JsonValue.Create(v)).ToArray());
        return (new JsonObject { ["versions"] = versions }, url);
    }

    static string SiteDataUrl(CollectCtx c, string site)
    {
        var path = Path.Combine(c.Root, "tools", "ai", "sites.json");
        var reg = JsonNode.Parse(File.ReadAllText(path)) as JsonObject ?? throw new CollectException("tools/ai/sites.json is not an object");
        var entry = J.Objs(reg["sites"]).FirstOrDefault(s => J.Str(s["id"]) == site) ?? throw new CollectException($"tools/ai/sites.json has no site '{site}'");
        var data = J.Str(entry["dataPath"]) ?? throw new CollectException($"site '{site}' has no dataPath");
        return $"{(J.Str(reg["baseUrl"]) ?? "").TrimEnd('/')}/{data.TrimStart('/')}";
    }

    static async Task<(JsonNode, string)> Pages(CollectCtx c, Fetcher f, string site)
    {
        var url = SiteDataUrl(c, site);
        var data = await f.HttpJsonAsync(url);
        var field = J.Str(J.Objs(((JsonObject)JsonNode.Parse(File.ReadAllText(Path.Combine(c.Root, "tools", "ai", "sites.json")))!)["sites"]).First(s => J.Str(s["id"]) == site)["timestampField"]) ?? "timestamp";
        var ts = J.Str(data?[field]) ?? throw new CollectException($"{url} has no top-level string '{field}'", url);
        return (new JsonObject { ["timestamp"] = ts, ["runId"] = J.Str(data?["runId"]) ?? J.Long(data?["runId"])?.ToString() }, url);
    }

    // Reads the published per-package, per-flag data; the targets and measurements are the dashboard's, never typed here.
    static async Task<(JsonNode, string)> CoverageFlags(CollectCtx c, Fetcher f)
    {
        var url = SiteDataUrl(c, "coverage");
        var data = await f.HttpJsonAsync(url);
        var failing = new JsonArray();
        var evaluated = 0;
        foreach (var p in J.Objs(data?["packages"]))
        {
            if (p["perFlagTarget"] is not JsonObject targets || targets.Count == 0) continue;
            evaluated++;
            foreach (var (flag, targetNode) in targets)
            {
                var target = J.Num(targetNode) ?? 0;
                var cov = J.Num(p["perFlag"]?[flag]?["coverage"]);
                if (cov is null || cov < target)
                    failing.Add(new JsonObject { ["package"] = J.Str(p["name"]), ["flag"] = flag, ["coverage"] = cov?.ToString("0.##", CultureInfo.InvariantCulture) ?? "n/a", ["target"] = target.ToString("0.##", CultureInfo.InvariantCulture) });
            }
        }
        if (evaluated == 0) throw new CollectException("the published coverage data exposes no per-package perFlagTarget; per-flag status cannot be assumed green", url);
        return (new JsonObject { ["timestamp"] = J.Str(data?["timestamp"]), ["packages"] = evaluated, ["failing"] = failing }, url);
    }

    // ---- Local checkout (synchronous; the source link points at the release commit) ----

    static (JsonNode, string) Local(FactRequest r, CollectCtx c)
    {
        string Src(string rel) => $"https://github.com/{c.Repo}/blob/{c.Sha}/{rel}";
        string Full(string rel) => Path.Combine(c.Root, rel.Replace('/', Path.DirectorySeparatorChar));
        switch (r.Collector)
        {
            case "skip-scan": return (SkipScan(c.Root), Src("tests"));
            case "file":
            {
                var rel = A(r, "path");
                return (new JsonObject { ["exists"] = FileMatches(Full(rel)).Any() }, Src(rel));
            }
            case "file-regex":
            {
                var rel = A(r, "path");
                var file = FileMatches(Full(rel)).FirstOrDefault();
                var matched = file is not null && Regex.IsMatch(File.ReadAllText(file), A(r, "pattern"), RegexOptions.Multiline | RegexOptions.CultureInvariant);
                return (new JsonObject { ["exists"] = file is not null, ["matched"] = matched }, Src(rel));
            }
            case "version-props":
            {
                var text = File.ReadAllText(Full("Directory.Build.props"));
                string Tag(string name) => Regex.Match(text, $"<{name}>([^<]*)</{name}>").Groups[1].Value.Trim();
                return (new JsonObject { ["prefix"] = Tag("VersionPrefix"), ["suffix"] = Tag("VersionSuffix") }, Src("Directory.Build.props"));
            }
            case "changelog":
            {
                var sections = new JsonArray();
                foreach (var line in File.ReadLines(Full("CHANGELOG.md")))
                {
                    var m = Regex.Match(line, @"^## \[([^\]]+)\](?: - (\d{4}-\d{2}-\d{2}))?");
                    if (m.Success) sections.Add(new JsonObject { ["version"] = m.Groups[1].Value, ["date"] = m.Groups[2].Success ? m.Groups[2].Value : null });
                }
                return (new JsonObject { ["sections"] = sections }, Src("CHANGELOG.md"));
            }
            case "unshipped": return (Unshipped(c.Root), Src("src"));
            case "ci-result-needs": return (CiResultNeeds(Full(".github/workflows/ci.yml")), Src(".github/workflows/ci.yml"));
            case "spec-verified":
            {
                var rel = A(r, "path");
                var m = Regex.Match(File.ReadAllText(Full(rel)), @"Verified on \*\*(\d{4}-\d{2}-\d{2})\*\*");
                return (new JsonObject { ["date"] = m.Success ? m.Groups[1].Value : null }, Src(rel));
            }
            case "dirs":
            {
                var counts = new JsonObject();
                foreach (var glob in A(r, "globs").Split('|'))
                {
                    var parent = Full(Path.GetDirectoryName(glob.Replace('/', Path.DirectorySeparatorChar)) ?? "");
                    counts[glob] = Directory.Exists(parent) ? Directory.EnumerateDirectories(parent, Path.GetFileName(glob)).Count() : 0;
                }
                return (new JsonObject { ["counts"] = counts }, Src("src"));
            }
            default: throw new CollectException($"unknown collector '{r.Collector}'");
        }
    }

    // A path whose last segment may contain a * wildcard.
    static IEnumerable<string> FileMatches(string full)
    {
        var dir = Path.GetDirectoryName(full)!;
        return Directory.Exists(dir) ? Directory.EnumerateFiles(dir, Path.GetFileName(full)).OrderBy(x => x, StringComparer.Ordinal) : [];
    }

    static IEnumerable<string> SourceFiles(string dir, string pattern) =>
        Directory.Exists(dir)
            ? Directory.EnumerateFiles(dir, pattern, SearchOption.AllDirectories)
                .Where(p => !p.Contains($"{Path.DirectorySeparatorChar}obj{Path.DirectorySeparatorChar}") && !p.Contains($"{Path.DirectorySeparatorChar}bin{Path.DirectorySeparatorChar}"))
                .OrderBy(p => p, StringComparer.Ordinal)
            : [];

    static string Rel(string root, string full) => Path.GetRelativePath(root, full).Replace('\\', '/');

    // AC-006: every Skip= references an issue (#nnn) on the same line or the line above.
    public static JsonNode SkipScan(string root)
    {
        var unreferenced = new JsonArray();
        var total = 0;
        foreach (var file in SourceFiles(Path.Combine(root, "tests"), "*.cs"))
        {
            var lines = File.ReadAllLines(file);
            for (var n = 0; n < lines.Length; n++)
            {
                if (!Regex.IsMatch(lines[n], @"\bSkip\s*=") || lines[n].TrimStart().StartsWith("//", StringComparison.Ordinal)) continue;
                total++;
                var ok = Regex.IsMatch(lines[n], @"#\d+") || (n > 0 && Regex.IsMatch(lines[n - 1], @"#\d+"));
                if (!ok) unreferenced.Add(JsonValue.Create($"{Rel(root, file)}:{n + 1}"));
            }
        }
        return new JsonObject { ["total"] = total, ["unreferenced"] = unreferenced };
    }

    public static JsonNode Unshipped(string root)
    {
        var bad = new JsonArray();
        var total = 0;
        foreach (var file in SourceFiles(Path.Combine(root, "src"), "PublicAPI.Unshipped.txt"))
        {
            total++;
            if (File.ReadLines(file).Any(l => l.Trim().Length > 0 && !l.TrimStart().StartsWith("#nullable", StringComparison.Ordinal))) bad.Add(JsonValue.Create(Rel(root, file)));
        }
        return new JsonObject { ["total"] = total, ["nonEmpty"] = bad };
    }

    public static JsonNode CiResultNeeds(string ciYml)
    {
        var lines = File.ReadAllLines(ciYml);
        var jobStart = new Regex(@"^  ([A-Za-z0-9_-]+):\s*$");
        var testJobs = new JsonArray();
        var needs = new JsonArray();
        var ifAlways = false;
        var inResult = false;
        var inJobs = false;
        foreach (var line in lines)
        {
            if (line.StartsWith("jobs:", StringComparison.Ordinal)) { inJobs = true; continue; }
            if (!inJobs) continue;
            var m = jobStart.Match(line);
            if (m.Success)
            {
                inResult = m.Groups[1].Value == "ci-result";
                if (m.Groups[1].Value.StartsWith("test-", StringComparison.Ordinal)) testJobs.Add(JsonValue.Create(m.Groups[1].Value));
                continue;
            }
            if (!inResult) continue;
            var nm = Regex.Match(line, @"^    needs:\s*\[(.*)\]\s*$");
            if (nm.Success) foreach (var n in nm.Groups[1].Value.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)) needs.Add(JsonValue.Create(n));
            if (Regex.IsMatch(line, @"^    if:\s*always\(\)\s*$")) ifAlways = true;
        }
        return new JsonObject { ["needs"] = needs, ["testJobs"] = testJobs, ["ifAlways"] = ifAlways };
    }
}

// =============================================================================================
// Reports: evaluation text, checklist, PR body, evidence. Deterministic: stable order, invariant
// culture, LF newlines, no clock reads.
// =============================================================================================

static class Report
{
    static string Sources(Item i) => string.Join(", ", i.Sources);

    static string Line(ItemResult r) => r.Status == "SKIP"
        ? $"SKIP {r.Item.Id} — {r.Reason}"
        : $"{r.Status} {r.Item.Id} {r.Item.Title} ({Sources(r.Item)}) — {r.Reason}";

    public static string EvaluationText(EvalRun run, FactsFile facts)
    {
        var sb = new StringBuilder();
        sb.Append($"Release readiness for v{run.Version} ({run.Profile}); facts collected {facts.CollectedAtUtc} at {J.Short(facts.Sha)} by {facts.Collector}\n");
        foreach (var r in run.Results) sb.Append(Line(r)).Append('\n');
        sb.Append($"SUMMARY profile={run.Profile} version={run.Version} pass={run.Count("PASS")} fail={run.Count("FAIL")} warn={run.Count("WARN")} pending={run.Count("PENDING")} skip={run.Count("SKIP")} result={(run.Passed ? "PASS" : "FAIL")}\n");
        return sb.ToString();
    }

    public static string SummaryMarkdown(EvalRun run, FactsFile facts)
    {
        var sb = new StringBuilder();
        sb.Append($"### Release readiness: v{run.Version} ({run.Profile}), result {(run.Passed ? "PASS" : "FAIL")}\n\n");
        sb.Append($"Facts collected {facts.CollectedAtUtc} at `{J.Short(facts.Sha)}` by {facts.Collector}.\n\n");
        sb.Append("| Status | Item | Source | Reason |\n| --- | --- | --- | --- |\n");
        foreach (var r in run.Results.Where(r => r.Status != "SKIP"))
            sb.Append($"| {r.Status} | `{r.Item.Id}` | {Sources(r.Item).Replace("|", "\\|", StringComparison.Ordinal)} | {r.Reason.Replace("|", "\\|", StringComparison.Ordinal)} |\n");
        sb.Append('\n');
        return sb.ToString();
    }

    static IEnumerable<Item> Active(Registry reg, string profile) => reg.Items.Where(i => !i.IsRetired && i.SeverityFor(profile) != "skip");

    public static string Checklist(Registry reg, string version, string profile)
    {
        var sb = new StringBuilder();
        sb.Append("---\n");
        sb.Append($"title: \"v{version} release checklist\"\nlayout: default\nnav_exclude: true\n---\n\n");
        sb.Append($"# v{version} release checklist\n\n");
        sb.Append($"> **Profile**: `{profile}`. Rendered by `.github/scripts/release-readiness.cs --render-checklist` from `.github/release-checklist.json`. ");
        sb.Append("The gate checks the automatic items itself; answer each manual item below by ticking it and adding an evidence link. A ticked line without a link counts as unanswered.\n\n");
        sb.Append("## Automatic items (checked by the gate)\n\n| Id | Item | Severity | Source |\n| --- | --- | --- | --- |\n");
        foreach (var i in Active(reg, profile).Where(i => i.Kind != "manual"))
            sb.Append($"| `{i.Id}` | {i.Title} | {i.SeverityFor(profile)} | {Sources(i)} |\n");
        sb.Append("\n## Manual items\n\n");
        if (!Active(reg, profile).Any(i => i.Kind == "manual")) sb.Append("No manual item in this profile.\n\n");
        foreach (var sev in new[] { "block", "warn" })
        {
            var items = Active(reg, profile).Where(i => i.Kind == "manual" && i.SeverityFor(profile) == sev).ToList();
            if (items.Count == 0) continue;
            sb.Append(sev == "block" ? "### Blocking\n\n" : "### Warning only\n\n");
            foreach (var i in items) sb.Append($"- [ ] {i.Id} — {i.Title} — evidence: <link>\n");
            sb.Append('\n');
        }
        sb.Append("## Milestone allow-list\n\nOne line per issue that may stay open in the release milestone:\n\n<!-- - allow-open: #123 — reason -->\n\n");
        sb.Append("## Medium-finding dispositions\n\nOne line per medium finding listed in the evidence report (`codeql#<number>` or `sonar:<key>`):\n\n<!-- - disposition: codeql#12 — accepted: reason -->\n");
        return sb.ToString();
    }

    public static string PrBody(string version, string profile, EvalRun? run)
    {
        var sb = new StringBuilder();
        sb.Append($"### Release readiness (v{version}, {profile})\n\n");
        sb.Append(run is null
            ? "Run the gate (`--collect`, then `--evaluate`) and paste the result here.\n"
            : $"Result: **{(run.Passed ? "PASS" : "FAIL")}** ({run.Count("PASS")} pass, {run.Count("FAIL")} fail, {run.Count("PENDING")} pending, {run.Count("WARN")} warn, {run.Count("SKIP")} skipped).\n");
        sb.Append($"\n- Checklist: `docs/releases/v{version}/checklist.md`\n- Evidence: `docs/releases/v{version}/evidence.md`\n- Facts: `docs/releases/v{version}/facts.json`\n");
        return sb.ToString();
    }

    public static string Evidence(Registry reg, EvalRun run, FactsFile facts, Signoff signoff)
    {
        var sb = new StringBuilder();
        sb.Append("---\n");
        sb.Append($"title: \"v{run.Version} release evidence\"\nlayout: default\nnav_exclude: true\n---\n\n");
        sb.Append($"# v{run.Version} release evidence\n\n");
        sb.Append("> Generated by `.github/scripts/release-readiness.cs --evidence` from `facts.json` (SPEC-000 AC-022). Do not edit by hand: regenerate it from the committed facts. ");
        sb.Append("Every statement below quotes a collected fact and links its source; no figure is typed.\n\n");
        sb.Append("| Field | Value |\n| --- | --- |\n");
        sb.Append($"| Version | {run.Version} |\n| Profile | {run.Profile} |\n| Commit | `{facts.Sha}` |\n| Facts collected (UTC) | {facts.CollectedAtUtc} |\n| Collector | {facts.Collector} |\n");
        sb.Append($"| Result | {(run.Passed ? "PASS" : "FAIL")} ({run.Count("PASS")} pass, {run.Count("FAIL")} fail, {run.Count("PENDING")} pending, {run.Count("WARN")} warn, {run.Count("SKIP")} skipped) |\n\n");

        foreach (var group in Registry.Groups)
        {
            var rows = run.Results.Where(r => r.Item.Group == group && r.Status != "SKIP").ToList();
            if (rows.Count == 0) continue;
            sb.Append($"## {group}\n\n");
            foreach (var r in rows)
            {
                sb.Append($"### `{r.Item.Id}`: {r.Item.Title}\n\n- Verdict: **{r.Status}**\n- Source: {Sources(r.Item)}\n- Reason: {r.Reason}\n");
                foreach (var key in r.FactKeys.Distinct(StringComparer.Ordinal))
                {
                    var f = facts.Facts.GetValueOrDefault(key);
                    sb.Append(f is null ? $"- Fact `{key}`: missing\n" : $"- Fact `{key}`: {(f.Source.Length > 0 ? $"<{f.Source}>" : "no source")}, retrieved {f.RetrievedAtUtc}{(f.Error is not null ? $", error: {f.Error}" : "")}\n");
                }
                sb.Append('\n');
            }
        }
        AppendFindings(sb, facts, signoff);
        AppendProtection(sb, facts);
        AppendDashboards(sb, facts);
        sb.Append("## Skipped and retired items\n\n");
        var skipped = run.Results.Where(r => r.Status == "SKIP").Select(r => $"`{r.Item.Id}`").ToList();
        sb.Append($"- Skipped in the {run.Profile} profile: {(skipped.Count == 0 ? "none" : string.Join(", ", skipped))}\n");
        foreach (var i in reg.Items.Where(i => i.IsRetired)) sb.Append($"- Retired `{i.Id}` ({i.RetiredRef}): {i.RetiredReason}\n");
        return sb.ToString();
    }

    static void AppendFindings(StringBuilder sb, FactsFile facts, Signoff signoff)
    {
        var rows = new List<(string Ref, string Detail, string Url)>();
        if (facts.Facts.GetValueOrDefault("code-scanning-alerts") is { Error: null, Value: { } cs })
            foreach (var a in J.Objs(cs["alerts"]).Where(a => J.Str(a["severity"]) == "medium"))
                rows.Add(($"codeql#{J.Int(a["number"])}", $"CodeQL medium, rule {J.Str(a["rule"])}", J.Str(a["url"]) ?? ""));
        string note = "";
        if (facts.Facts.GetValueOrDefault("sonar-issues") is { Error: null, Value: { } sq })
        {
            foreach (var i in J.Objs(sq["mediumIssues"])) rows.Add(($"sonar:{J.Str(i["key"])}", $"SonarCloud medium, rule {J.Str(i["rule"])}, {J.Str(i["component"])}", ""));
            var total = J.Int(sq["medium"]) ?? 0;
            var listed = J.Arr(sq["mediumIssues"]).Count;
            if (total > listed) note = $"SonarCloud reports {total} medium issues; the first {listed} are listed.\n\n";
        }
        sb.Append("## Medium findings and their dispositions (SPEC-000 DEC-004)\n\n");
        if (rows.Count == 0) { sb.Append($"No medium finding in the collected facts.\n\n{note}"); return; }
        sb.Append("| Ref | Finding | Link | Disposition |\n| --- | --- | --- | --- |\n");
        foreach (var (r, detail, url) in rows)
            sb.Append($"| `{r}` | {detail} | {(url.Length > 0 ? $"<{url}>" : "")} | {(signoff.Dispositions.TryGetValue(r, out var d) ? d.Replace("|", "\\|", StringComparison.Ordinal) : "not dispositioned")} |\n");
        sb.Append($"\n{note}");
    }

    static void AppendProtection(StringBuilder sb, FactsFile facts)
    {
        if (facts.Facts.GetValueOrDefault("branch-protection") is not { } f) return;
        sb.Append("## Branch protection of `main` (SPEC-000 AC-020)\n\n");
        if (f.Error is not null || f.Value?["protection"] is null) { sb.Append($"Not collected: {f.Error ?? "no data"}\n\n"); return; }
        sb.Append($"Source: <{f.Source}>, retrieved {f.RetrievedAtUtc}.\n\n```json\n");
        sb.Append(f.Value["protection"]!.ToJsonString(new JsonSerializerOptions { WriteIndented = true }).Replace("\r\n", "\n", StringComparison.Ordinal));
        sb.Append("\n```\n\n");
    }

    static void AppendDashboards(StringBuilder sb, FactsFile facts)
    {
        var rows = facts.Facts.Where(kv => kv.Key.StartsWith("pages:", StringComparison.Ordinal) || kv.Key == "coverage-flags").ToList();
        if (rows.Count == 0) return;
        sb.Append("## Dashboards\n\n| Data | Source | Retrieved (UTC) |\n| --- | --- | --- |\n");
        foreach (var (k, f) in rows) sb.Append($"| `{k}` | {(f.Source.Length > 0 ? $"<{f.Source}>" : "")} | {f.RetrievedAtUtc} |\n");
        sb.Append('\n');
    }
}

// =============================================================================================
// --self-test: offline, deterministic. Fixtures live in .github/scripts/fixtures/release-readiness/.
// =============================================================================================

sealed class FixedTime(DateTimeOffset now) : TimeProvider
{
    public override DateTimeOffset GetUtcNow() => now;
}

sealed class FakeRemote(Func<string, string?, Response> gh) : IRemote
{
    public List<(string Endpoint, string? Token)> Calls { get; } = [];

    public Task<Response> GhAsync(string endpoint, string? token)
    {
        Calls.Add((endpoint, token));
        return Task.FromResult(gh(endpoint, token));
    }

    public Task<Response> HttpAsync(string url) => Task.FromResult(new Response(0, "", new Dictionary<string, string>(), "no network in self-test"));
}

static class SelfTest
{
    const string Sha = "0123456789abcdef0123456789abcdef01234567";
    static readonly DateTimeOffset Now = DateTimeOffset.Parse("2026-10-20T06:00:00Z", CultureInfo.InvariantCulture);
    static int failed;
    static int passed;
    static TextWriter outw = null!;

    static void Case(string name, Func<string?> body)
    {
        string? problem;
        try { problem = body(); }
        catch (Exception ex) { problem = $"threw {ex.GetType().Name}: {ex.Message}"; }
        if (problem is null) { passed++; outw.WriteLine($"SELFTEST ok {name}"); }
        else { failed++; outw.WriteLine($"SELFTEST FAIL {name}: {problem}"); }
    }

    static string? Expect(bool condition, string detail) => condition ? null : detail;

    public static async Task<int> RunAsync(Env env, string? rootArg)
    {
        outw = env.Out;
        failed = passed = 0;
        var root = rootArg ?? Cli.FindRepoRoot(env.Cwd);
        var fx = Path.Combine(root, ".github", "scripts", "fixtures", "release-readiness");
        if (!Directory.Exists(fx)) { env.Err.WriteLine($"error: fixtures not found: {fx}"); return 2; }

        RegistryCases(env, root, fx);
        EvaluatorCases(fx);
        PipelineCases(env, root, fx);
        BranchCases(env, root);
        await CollectorCases(env, fx);
        LocalCollectorCases(env, fx);
        AttestationCases(fx);

        outw.WriteLine($"SELFTEST summary: {passed} ok, {failed} failed");
        return failed == 0 ? 0 : 1;
    }

    static Env TestEnv(Env baseEnv, StringWriter o, StringWriter e, string cwd, IRemote? remote = null, Func<string, string?>? getEnv = null, List<TimeSpan>? delays = null) => new()
    {
        Out = o, Err = e, Cwd = cwd, Remote = remote ?? new FakeRemote((_, _) => new Response(0, "", new Dictionary<string, string>(), "offline")),
        Clock = new FixedTime(Now), Delay = t => { delays?.Add(t); return Task.CompletedTask; }, GetEnv = getEnv ?? (_ => null),
        CollectorIdentity = () => Task.FromResult("selftest"),
    };

    static (int Code, string Out, string Err) Run(Env baseEnv, string cwd, params string[] args)
    {
        var o = new StringWriter { NewLine = "\n" };
        var e = new StringWriter { NewLine = "\n" };
        var code = Cli.RunAsync(args, TestEnv(baseEnv, o, e, cwd)).GetAwaiter().GetResult();
        return (code, o.ToString(), e.ToString());
    }

    static string Hash(string s) => Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(s)));

    // ---- Registry ----

    static void RegistryCases(Env env, string root, string fx)
    {
        (int Code, string Out, string Err) Check(string file, string r) => Run(env, root, "--check-registry", "--registry", Path.Combine(fx, file), "--root", r);
        Case("registry valid", () => { var r = Check("registry-valid.json", fx); return Expect(r.Code == 0, $"exit {r.Code}: {r.Err}"); });
        Case("registry duplicate id", () => { var r = Check("registry-duplicate-id.json", fx); return Expect(r.Code == 2 && r.Err.Contains("duplicate item id"), $"exit {r.Code}: {r.Err}"); });
        Case("registry unknown evaluator", () => { var r = Check("registry-unknown-evaluator.json", fx); return Expect(r.Code == 2 && r.Err.Contains("unknown evaluator"), $"exit {r.Code}: {r.Err}"); });
        Case("registry missing acceptance criterion", () => { var r = Check("registry-missing-ac.json", fx); return Expect(r.Code == 2 && r.Err.Contains("SPEC-000 AC-003 has no registry entry"), $"exit {r.Code}: {r.Err}"); });
        var text = File.ReadAllText(Path.Combine(fx, "registry-valid.json"));
        void Mutated(string name, string from, string to, string expected) => Case(name, () =>
        {
            var errors = new List<string>();
            var res = Registry.Parse(text.Replace(from, to, StringComparison.Ordinal), fx, errors);
            return Expect(res.Registry is null && errors.Any(x => x.Contains(expected)), $"expected '{expected}', got [{string.Join("; ", errors)}]");
        });
        Mutated("registry rejects an unknown severity", "\"minor\": \"block\"", "\"minor\": \"loud\"", "profiles.minor must be one of");
        Mutated("registry rejects a source that is not a SPEC acceptance criterion", "\"SPEC-000 AC-003\"", "\"SPEC-000 AC-099\"", "not an acceptance criterion");
        Mutated("registry rejects a retired item without a reason", "\"reason\": \"Superseded", "\"why\": \"Superseded", "needs retired.reason");
        Mutated("registry rejects a parameter of the wrong type", "\"maxAgeDays\": 30", "\"maxAgeDays\": \"30\"", "'maxAgeDays' must be of type i");
        Case("the real registry is valid", () => { var r = Run(env, root, "--check-registry", "--root", root); return Expect(r.Code == 0, $"exit {r.Code}: {r.Err}"); });
    }

    // ---- One passing and one failing case per evaluator ----

    static void EvaluatorCases(string fx)
    {
        var cases = JsonNode.Parse(File.ReadAllText(Path.Combine(fx, "evaluator-cases.json"))) as JsonArray ?? throw new InvalidDataException("evaluator-cases.json must be an array");
        var coverage = new Dictionary<string, HashSet<string>>(StringComparer.Ordinal);
        foreach (var node in cases.OfType<JsonObject>())
        {
            var name = J.Str(node["name"]) ?? "case";
            var checkName = J.Str(node["check"]?["name"]) ?? "?";
            var expect = J.Str(node["expect"]) ?? "PASS";
            coverage.TryAdd(checkName, []);
            coverage[checkName].Add(expect);
            Case($"evaluator {name}", () =>
            {
                var version = J.Str(node["version"]) ?? "0.14.0";
                var profile = J.Str(node["profile"]) ?? "rc";
                var now = Time.Parse(J.Str(node["now"]) ?? "2026-10-20T00:00:00Z")!.Value;
                var parameters = node["check"]?["params"] as JsonObject ?? new JsonObject();
                var kind = J.Str(node["kind"]) ?? "auto";
                var problems = Evaluators.Table.TryGetValue(checkName, out var def) ? ParamSpec.Validate(def.ParamSpec, parameters) : [$"unknown evaluator {checkName}"];
                if (problems.Count > 0) return $"fixture params invalid: {string.Join("; ", problems)}";
                var item = new Item("case", "case", ["#104"], [], kind, "Release", checkName, (JsonObject)parameters.DeepClone(),
                    new Dictionary<string, string> { ["minor"] = "block", ["rc"] = "block", ["final"] = "block" }, null, null, null);
                var facts = new SortedDictionary<string, Fact>(StringComparer.Ordinal);
                foreach (var (key, f) in node["facts"] as JsonObject ?? new JsonObject())
                    facts[key] = new Fact(f?["value"]?.DeepClone(), "https://example.invalid/" + key, "2026-10-20T00:00:00Z", J.Str(f?["error"]), 1);
                var sha = J.Str(node["sha"]) ?? Sha;
                var file = new FactsFile(1, version, profile, sha, Time.Format(now), "selftest", facts);
                var signoff = Signoff.Parse(J.Str(node["signoff"]) ?? "");
                var run = Engine.Run(new Registry([], [item]), new EvalCtx(file, signoff, now), null);
                var r = run.Results[0];
                if (r.Status != expect) return $"expected {expect}, got {r.Status}: {r.Reason}";
                var contains = J.Str(node["contains"]);
                return contains is null || r.Reason.Contains(contains, StringComparison.Ordinal) ? null : $"reason lacks '{contains}': {r.Reason}";
            });
        }
        Case("every evaluator has a passing and a failing case", () =>
        {
            var missing = Evaluators.Table.Keys.Where(k => k != "alias").Where(k => !coverage.TryGetValue(k, out var s) || !s.Contains("PASS") || !s.Contains("FAIL")).ToList();
            return Expect(missing.Count == 0, $"no PASS and FAIL case for: {string.Join(", ", missing)}");
        });
    }

    // ---- Whole-pipeline cases against the fixture registry ----

    static void PipelineCases(Env env, string root, string fx)
    {
        string P(string f) => Path.Combine(fx, f);
        (int Code, string Out, string Err) Eval(string facts, string version, string? signoff = null, string now = "2026-10-20T06:00:00Z", string[]? extra = null)
        {
            var args = new List<string> { "--evaluate", "--registry", P("registry-valid.json"), "--root", fx, "--facts", P(facts), "--version", version, "--now", now };
            if (signoff is not null) { args.Add("--signoff"); args.Add(P(signoff)); }
            args.AddRange(extra ?? []);
            return Run(env, root, args.ToArray());
        }
        Case("minor passes with a clean fixture", () => { var r = Eval("facts-minor-clean.json", "0.14.0"); return Expect(r.Code == 0 && r.Out.Contains("result=PASS"), $"exit {r.Code}\n{r.Out}{r.Err}"); });
        Case("minor fails on a law-map date 31 days old", () => { var r = Eval("facts-minor-law-map-31d.json", "0.14.0"); return Expect(r.Code == 1 && r.Out.Contains("FAIL law-map-date") && r.Out.Contains("31 days"), $"exit {r.Code}\n{r.Out}"); });
        Case("minor skips the items its profile does not carry", () => { var r = Eval("facts-minor-clean.json", "0.14.0"); return Expect(r.Out.Contains("SKIP codeql-high-alerts"), r.Out); });
        Case("rc fails on one open high CodeQL alert", () => { var r = Eval("facts-rc-high-alert.json", "1.0.0-rc.1", "signoff-ticked-evidence.md"); return Expect(r.Code == 1 && r.Out.Contains("FAIL codeql-high-alerts"), $"exit {r.Code}\n{r.Out}"); });
        Case("final fails on one non-empty Unshipped file", () => { var r = Eval("facts-final-unshipped.json", "1.0.0", "signoff-ticked-evidence.md"); return Expect(r.Code == 1 && r.Out.Contains("FAIL unshipped-empty"), $"exit {r.Code}\n{r.Out}"); });
        Case("rc warns, not fails, on a non-empty Unshipped file", () => { var r = Eval("facts-rc-unshipped.json", "1.0.0-rc.1", "signoff-ticked-evidence.md"); return Expect(r.Code == 0 && r.Out.Contains("WARN unshipped-empty"), $"exit {r.Code}\n{r.Out}"); });
        Case("fail closed: an error fact on a block item fails it", () => { var r = Eval("facts-error.json", "1.0.0-rc.1", "signoff-ticked-evidence.md"); return Expect(r.Code == 1 && r.Out.Contains("FAIL codeql-high-alerts") && !r.Out.Contains("PASS codeql-high-alerts") && r.Out.Contains("could not be collected"), $"exit {r.Code}\n{r.Out}"); });
        Case("fail closed: a missing fact fails its item", () =>
        {
            var reg = Registry.Load(P("registry-valid.json"), fx).Registry!;
            var f = FactsFile.Read(P("facts-rc-clean.json"));
            var facts = f.Facts.Where(kv => kv.Key != "code-scanning-alerts").ToDictionary(kv => kv.Key, kv => kv.Value);
            var run = Engine.Run(reg, new EvalCtx(f with { Facts = facts }, Signoff.Parse(File.ReadAllText(P("signoff-ticked-evidence.md"))), Now), null);
            return Expect(run.Results.Any(r => r.Item.Id == "codeql-high-alerts" && r.Status == "FAIL" && r.Reason.Contains("missing")) && !run.Passed, "missing fact did not fail");
        });
        Case("stale facts are rejected", () => { var r = Eval("facts-stale.json", "0.14.0"); return Expect(r.Code == 1 && r.Err.Contains("REJECTED facts: facts are stale"), $"exit {r.Code}\n{r.Err}"); });
        Case("facts for another version are rejected", () => { var r = Eval("facts-wrong-version.json", "0.14.0"); return Expect(r.Code == 1 && r.Err.Contains("REJECTED facts: facts were collected for version 0.13.0"), $"exit {r.Code}\n{r.Err}"); });
        Case("facts for another profile are rejected", () => { var r = Eval("facts-minor-clean.json", "0.14.0", extra: ["--profile", "rc"]); return Expect(r.Code == 1 && r.Err.Contains("REJECTED facts: facts were collected for profile minor"), $"exit {r.Code}\n{r.Err}"); });
        Case("a manual item ticked with evidence passes", () => { var r = Eval("facts-rc-clean.json", "1.0.0-rc.1", "signoff-ticked-evidence.md"); return Expect(r.Code == 0 && r.Out.Contains("PASS adversarial-review"), $"exit {r.Code}\n{r.Out}"); });
        Case("a manual item ticked without evidence is unanswered", () => { var r = Eval("facts-rc-clean.json", "1.0.0-rc.1", "signoff-ticked-no-evidence.md"); return Expect(r.Code == 1 && r.Out.Contains("PENDING adversarial-review") && r.Out.Contains("without an evidence link"), $"exit {r.Code}\n{r.Out}"); });
        Case("an unticked manual item is unanswered", () => { var r = Eval("facts-rc-clean.json", "1.0.0-rc.1", "signoff-unticked.md"); return Expect(r.Code == 1 && r.Out.Contains("PENDING adversarial-review"), $"exit {r.Code}\n{r.Out}"); });
        Case("--only limits the evaluation and rejects unknown ids", () =>
        {
            var one = Eval("facts-minor-clean.json", "0.14.0", extra: ["--only", "law-map-date"]);
            var bad = Eval("facts-minor-clean.json", "0.14.0", extra: ["--only", "no-such-item"]);
            return Expect(one.Code == 0 && one.Out.Split('\n').Count(l => l.StartsWith("PASS ", StringComparison.Ordinal)) == 1 && bad.Code == 2, $"only: {one.Code}\n{one.Out}; unknown: {bad.Code}");
        });
        Case("determinism: --evaluate gives identical output twice", () =>
        {
            var a = Eval("facts-rc-clean.json", "1.0.0-rc.1", "signoff-ticked-evidence.md");
            var b = Eval("facts-rc-clean.json", "1.0.0-rc.1", "signoff-ticked-evidence.md");
            return Expect(a.Code == 0 && Hash(a.Out) == Hash(b.Out), "outputs differ");
        });
        Case("determinism and sources: --evidence is byte-identical and quotes the fact sources", () =>
        {
            var tmp = Path.Combine(Path.GetTempPath(), $"release-readiness-selftest-{Guid.NewGuid():N}");
            try
            {
                string Gen(string name)
                {
                    var r = Run(env, root, "--evidence", "--registry", P("registry-valid.json"), "--root", fx, "--facts", P("facts-rc-clean.json"), "--signoff", P("signoff-ticked-evidence.md"), "--out", Path.Combine(tmp, name));
                    return r.Code == 0 ? File.ReadAllText(Path.Combine(tmp, name)) : $"exit {r.Code}: {r.Err}";
                }
                var a = Gen("a.md");
                var b = Gen("b.md");
                return Expect(Hash(a) == Hash(b) && a.Contains("<https://example.invalid/ci-full>") && a.Contains("retrieved 2026-10-20T00:00:00Z") && a.Contains("## Build and quality gates") && a.Contains("Retired `old-coverage-target`"),
                    $"evidence differs or lacks sources:\n{a[..Math.Min(a.Length, 600)]}");
            }
            finally { if (Directory.Exists(tmp)) Directory.Delete(tmp, true); }
        });
        Case("--render-checklist matches the golden file", () =>
        {
            var r = Run(env, root, "--render-checklist", "--registry", P("registry-valid.json"), "--root", fx, "--profile", "rc", "--version", "1.0.0-rc.1");
            var golden = File.ReadAllText(P("checklist-rc.golden.md")).Replace("\r\n", "\n", StringComparison.Ordinal);
            return Expect(r.Code == 0 && r.Out == golden, $"render differs from checklist-rc.golden.md (exit {r.Code}):\n{r.Out}");
        });
        Case("--render-checklist --format pr-body links the three files", () =>
        {
            var r = Run(env, root, "--render-checklist", "--registry", P("registry-valid.json"), "--root", fx, "--profile", "rc", "--version", "1.0.0-rc.1", "--format", "pr-body", "--facts", P("facts-rc-clean.json"));
            return Expect(r.Code == 0 && r.Out.Contains("docs/releases/v1.0.0-rc.1/evidence.md") && r.Out.Contains("Result:"), r.Out + r.Err);
        });
    }

    // ---- Branch name to profile ----

    static void BranchCases(Env env, string root)
    {
        void Maps(string branch, string expected) => Case($"branch {branch} maps to {expected}", () =>
        {
            var r = Run(env, root, "--from-branch", branch);
            return Expect(r.Code == 0 && r.Out.Contains($"profile={expected}"), $"exit {r.Code}: {r.Out}{r.Err}");
        });
        void Rejected(string branch) => Case($"branch {branch} is an error, not the lightest profile", () =>
        {
            var r = Run(env, root, "--from-branch", branch);
            return Expect(r.Code == 2 && !r.Out.Contains("profile="), $"exit {r.Code}: {r.Out}{r.Err}");
        });
        Maps("release/v0.14.0", "minor");
        Maps("release/v1.1.0", "minor");
        Maps("release/v1.0.0-rc.1", "rc");
        Maps("release/v1.0.0-rc.12", "rc");
        Maps("release/v1.0.0", "final");
        Rejected("release/vnext");
        Rejected("feature/release-v0.14.0");
        Rejected("release/v0.14.1");
        Rejected("release/v1.0.0-beta.1");
        Rejected("release/v0.14.0+build.5");
        Rejected("release/v01.0.0");
    }

    // ---- Collectors against a scripted remote: retry, the App token, fail closed ----

    static async Task CollectorCases(Env env, string fx)
    {
        CollectCtx Ctx(IRemote remote, string? token, List<TimeSpan>? delays = null) =>
            new(TestEnv(env, new StringWriter(), new StringWriter(), fx, remote, null, delays), "dlrivada/Encina", fx, "0.14.0", "rc", Sha, token);
        static Response Json(string body, int status = 200, params (string, string)[] headers) =>
            new(status, body, headers.ToDictionary(h => h.Item1, h => h.Item2, StringComparer.OrdinalIgnoreCase), null);
        var secretReq = new FactRequest("secret-scanning-alerts", "secret-scanning", new JsonObject());
        var dependabotReq = new FactRequest("dependabot-alerts", "dependabot", new JsonObject());
        var issueReq = new FactRequest("issue:7", "issue", new JsonObject { ["number"] = "7" });

        var present = new FakeRemote((ep, tok) => ep.Contains("secret-scanning/alerts", StringComparison.Ordinal) && tok == "app-token" ? Json("[]") : ep.Contains("dependabot/alerts", StringComparison.Ordinal) && tok == "app-token"
            ? Json("[{\"number\":4,\"security_advisory\":{\"severity\":\"high\"},\"dependency\":{\"package\":{\"name\":\"X\"}},\"html_url\":\"u\"}]")
            : Json("{\"number\":7,\"state\":\"closed\",\"title\":\"t\",\"labels\":[]}"));
        Case("App token present: the alert facts are collected with it", () =>
        {
            var s = OneSync(secretReq, Ctx(present, "app-token"));
            var d = OneSync(dependabotReq, Ctx(present, "app-token"));
            return Expect(s.Error is null && J.Arr(s.Value?["alerts"]).Count == 0 && d.Error is null && J.Arr(d.Value?["alerts"]).Count == 1, $"secret error {s.Error}; dependabot error {d.Error}");
        });
        Case("App token present: a high Dependabot alert fails the evaluator", () =>
        {
            var d = OneSync(dependabotReq, Ctx(present, "app-token"));
            var item = new Item("d", "d", ["#104"], [], "auto", "Release", "dependabot-alerts", new JsonObject { ["minSeverity"] = "medium" }, new Dictionary<string, string> { ["rc"] = "block" }, null, null, null);
            var run = Engine.Run(new Registry([], [item]), new EvalCtx(new FactsFile(1, "0.14.0", "rc", Sha, "2026-10-20T00:00:00Z", "t", new Dictionary<string, Fact> { ["dependabot-alerts"] = d }), Signoff.Empty, Now), null);
            return Expect(run.Results[0].Status == "FAIL", run.Results[0].Reason);
        });
        Case("App token only reaches the two alert collectors", () =>
        {
            OneSync(issueReq, Ctx(present, "app-token"));
            return Expect(present.Calls.Where(c => c.Endpoint.Contains("/issues/7", StringComparison.Ordinal)).All(c => c.Token is null), "the token was sent to a non-alert call");
        });
        Case("App token missing: the fact carries an error and no call is made", () =>
        {
            var remote = new FakeRemote((_, _) => Json("[]"));
            var f = OneSync(secretReq, Ctx(remote, null));
            return Expect(f.Error is not null && f.Error.Contains(Cli.AppTokenVariable) && remote.Calls.Count == 0, $"error {f.Error}, calls {remote.Calls.Count}");
        });
        var protectionReq = new FactRequest("branch-protection", "branch-protection", new JsonObject());
        Case("branch protection: read with the App token, keeping only the AC-020 fields", () =>
        {
            var remote = new FakeRemote((_, tok) => tok == "app-token"
                ? Json("{\"url\":\"u\",\"enforce_admins\":{\"enabled\":true,\"url\":\"x\"},\"required_pull_request_reviews\":{\"required_approving_review_count\":0,\"dismiss_stale_reviews\":true},\"required_conversation_resolution\":{\"enabled\":true},\"required_linear_history\":{\"enabled\":true},\"required_status_checks\":{\"strict\":true,\"contexts\":[\"build\",\"ci-result\",\"Analyze\"],\"checks\":[{\"context\":\"build\",\"app_id\":1}]},\"restrictions\":{\"users\":[]}}")
                : Json("{}", 403));
            var f = OneSync(protectionReq, Ctx(remote, "app-token"));
            var p = f.Value?["protection"] as JsonObject;
            var item = new Item("b", "b", ["#104"], [], "auto", "Release", "branch-protection", new JsonObject { ["contexts"] = new JsonArray("build", "ci-result", "Analyze") }, new Dictionary<string, string> { ["rc"] = "block" }, null, null, null);
            var run = Engine.Run(new Registry([], [item]), new EvalCtx(new FactsFile(1, "0.14.0", "rc", Sha, "2026-10-20T00:00:00Z", "t", new Dictionary<string, Fact> { ["branch-protection"] = f }), Signoff.Empty, Now), null);
            return Expect(f.Error is null && p is not null && p["restrictions"] is null && p["url"] is null && p["required_status_checks"]?["strict"] is null && remote.Calls.All(c => c.Token == "app-token") && run.Results[0].Status == "PASS", $"{f.Error} {f.Value?.ToJsonString()} {run.Results[0].Reason}");
        });
        Case("branch protection: token missing fails closed and names the remedy, without a call", () =>
        {
            var remote = new FakeRemote((_, _) => Json("{}"));
            var f = OneSync(protectionReq, Ctx(remote, null));
            return Expect(f.Error is not null && f.Error.Contains("Administration: Read-only") && f.Error.Contains(Cli.AppTokenVariable) && remote.Calls.Count == 0, f.Error ?? "no error");
        });
        Case("branch protection: a 403 fails closed, names the remedy and the item FAILs", () =>
        {
            var remote = new FakeRemote((_, _) => Json("{}", 403));
            var f = OneSync(protectionReq, Ctx(remote, "app-token"));
            var item = new Item("b", "b", ["#104"], [], "auto", "Release", "branch-protection", new JsonObject { ["contexts"] = new JsonArray("build") }, new Dictionary<string, string> { ["rc"] = "block" }, null, null, null);
            var run = Engine.Run(new Registry([], [item]), new EvalCtx(new FactsFile(1, "0.14.0", "rc", Sha, "2026-10-20T00:00:00Z", "t", new Dictionary<string, Fact> { ["branch-protection"] = f }), Signoff.Empty, Now), null);
            return Expect(f.Error is not null && f.Error.Contains("HTTP 403") && f.Error.Contains("Set up the GitHub App") && run.Results[0].Status == "FAIL", f.Error ?? "no error");
        });
        Case("branch protection: a 404 fails closed and names the remedy", () =>
        {
            var f = OneSync(protectionReq, Ctx(new FakeRemote((_, _) => Json("{}", 404)), "app-token"));
            return Expect(f.Error is not null && f.Error.Contains("HTTP 404") && f.Error.Contains("Administration: Read-only"), f.Error ?? "no error");
        });
        Case("App token failing: three attempts, the fact carries an error, the item fails closed", () =>
        {
            var delays = new List<TimeSpan>();
            var remote = new FakeRemote((_, _) => Json("{}", 500));
            var f = OneSync(secretReq, Ctx(remote, "app-token", delays));
            var item = new Item("s", "s", ["#104"], [], "auto", "Release", "secret-scanning-alerts", new JsonObject(), new Dictionary<string, string> { ["rc"] = "block" }, null, null, null);
            var run = Engine.Run(new Registry([], [item]), new EvalCtx(new FactsFile(1, "0.14.0", "rc", Sha, "2026-10-20T00:00:00Z", "t", new Dictionary<string, Fact> { ["secret-scanning-alerts"] = f }), Signoff.Empty, Now), null);
            return Expect(f.Error is not null && f.Attempts == 3 && remote.Calls.Count == 3 && delays.Count == 2 && delays[0] == TimeSpan.FromSeconds(1) && delays[1] == TimeSpan.FromSeconds(2) && run.Results[0].Status == "FAIL",
                $"error {f.Error}, attempts {f.Attempts}, delays {string.Join(",", delays)}, status {run.Results[0].Status}");
        });
        Case("retry honours Retry-After and recovers", () =>
        {
            var delays = new List<TimeSpan>();
            var n = 0;
            var remote = new FakeRemote((_, _) => ++n == 1 ? Json("{}", 429, ("Retry-After", "7")) : Json("[]"));
            var f = OneSync(secretReq, Ctx(remote, "app-token", delays));
            return Expect(f.Error is null && f.Attempts == 2 && delays.Count == 1 && delays[0] == TimeSpan.FromSeconds(7), $"error {f.Error}, attempts {f.Attempts}, delays {string.Join(",", delays)}");
        });
        Case("retry honours x-ratelimit-reset on a rate-limited 403", () =>
        {
            var delays = new List<TimeSpan>();
            var reset = Now.AddSeconds(20).ToUnixTimeSeconds().ToString(CultureInfo.InvariantCulture);
            var n = 0;
            var remote = new FakeRemote((_, _) => ++n == 1 ? Json("{}", 403, ("x-ratelimit-remaining", "0"), ("x-ratelimit-reset", reset)) : Json("[]"));
            var f = OneSync(secretReq, Ctx(remote, "app-token", delays));
            return Expect(f.Error is null && f.Attempts == 2 && delays.Count == 1 && delays[0] == TimeSpan.FromSeconds(20), $"error {f.Error}, attempts {f.Attempts}, delays {string.Join(",", delays)}");
        });
        Case("a 404 is not retried and is recorded as an error", () =>
        {
            var remote = new FakeRemote((_, _) => Json("{}", 404));
            var f = OneSync(issueReq, Ctx(remote, null));
            return Expect(f.Error is not null && f.Attempts == 1 && f.Error.Contains("HTTP 404"), $"error {f.Error}, attempts {f.Attempts}");
        });
        await Task.CompletedTask;
    }

    // ---- Local collectors against the fixture checkout ----

    static void LocalCollectorCases(Env env, string fx)
    {
        var co = Path.Combine(fx, "checkout");
        var ctx = new CollectCtx(TestEnv(env, new StringWriter(), new StringWriter(), fx), "dlrivada/Encina", co, "0.14.0", "rc", Sha, null);
        Fact Get(string collector, params (string, string)[] args)
        {
            var o = new JsonObject();
            foreach (var (k, v) in args) o[k] = v;
            return OneSync(new FactRequest("k", collector, o), ctx);
        }
        Case("local collector skip-scan finds the Skip= without an issue", () =>
        {
            var v = Collectors.SkipScan(co);
            var bad = J.Strs(v["unreferenced"]).ToList();
            return Expect(J.Int(v["total"]) == 3 && bad.Count == 1 && bad[0].EndsWith("SkipSample.cs:12", StringComparison.Ordinal), $"total {J.Int(v["total"])}, unreferenced {string.Join(",", bad)}");
        });
        Case("local collector unshipped lists only the non-empty file", () =>
        {
            var v = Collectors.Unshipped(co);
            return Expect(J.Int(v["total"]) == 2 && J.Strs(v["nonEmpty"]).SequenceEqual(["src/B/PublicAPI.Unshipped.txt"]), v.ToJsonString());
        });
        Case("local collector ci-result-needs parses the needs list and the test jobs", () =>
        {
            var v = Collectors.CiResultNeeds(Path.Combine(fx, "ci-needs-sample.yml"));
            return Expect(J.Strs(v["needs"]).Contains("test-guard") && J.Strs(v["testJobs"]).Count() == 2 && J.Bool(v["ifAlways"]) == true, v.ToJsonString());
        });
        Case("local collector version-props reads prefix and suffix", () =>
        {
            var f = Get("version-props");
            return Expect(f.Error is null && J.Str(f.Value?["prefix"]) == "0.14.0" && J.Str(f.Value?["suffix"]) == "dev", f.Error ?? f.Value?.ToJsonString() ?? "");
        });
        Case("local collector changelog reads dated and undated sections", () =>
        {
            var f = Get("changelog");
            var s = J.Objs(f.Value?["sections"]).ToList();
            return Expect(f.Error is null && s.Count == 3 && J.Str(s[0]["date"]) is null && J.Str(s[1]["date"]) == "2026-10-20", f.Error ?? f.Value?.ToJsonString() ?? "");
        });
        Case("local collector spec-verified reads the verification date", () =>
        {
            var f = Get("spec-verified", ("path", "docs/spec.md"));
            return Expect(J.Str(f.Value?["date"]) == "2026-09-23", f.Error ?? "wrong date");
        });
        Case("local collector file and file-regex answer exists and matched", () =>
        {
            var e = Get("file", ("path", "LICENSE"));
            var m = Get("file-regex", ("path", "LICENSE"), ("pattern", "^MIT License"));
            var n = Get("file", ("path", "global.json"));
            return Expect(J.Bool(e.Value?["exists"]) == true && J.Bool(m.Value?["matched"]) == true && J.Bool(n.Value?["exists"]) == false, "file facts wrong");
        });
        Case("local collector dirs counts matching directories", () =>
        {
            var f = Get("dirs", ("globs", "src/Encina.Secrets.*|src/Encina.Security.Secrets.*"));
            return Expect(J.Int(f.Value?["counts"]?["src/Encina.Security.Secrets.*"]) == 1 && J.Int(f.Value?["counts"]?["src/Encina.Secrets.*"]) == 0, f.Error ?? f.Value?.ToJsonString() ?? "");
        });
        Case("a local collector that cannot read its file records an error", () =>
        {
            var f = Get("spec-verified", ("path", "docs/missing.md"));
            return Expect(f.Error is not null && f.Value is null, "expected an error fact");
        });
    }

    static Fact OneSync(FactRequest req, CollectCtx c) => Collectors.OneAsync(req, c).GetAwaiter().GetResult();

    // ---- The attestation fallback ----

    static void AttestationCases(string fx)
    {
        var reg = Registry.Load(Path.Combine(fx, "registry-valid.json"), fx).Registry!;
        EvalRun Go(Fact secret, string signoff) => Engine.Run(reg, new EvalCtx(
            new FactsFile(1, "1.0.0-rc.1", "rc", Sha, "2026-10-20T00:00:00Z", "t", new Dictionary<string, Fact> { ["secret-scanning-alerts"] = secret }), Signoff.Parse(signoff), Now),
            new HashSet<string>(["secret-scanning-no-alerts", "attest-secret-scanning"], StringComparer.Ordinal));
        var errored = new Fact(null, "https://example.invalid/secret", "2026-10-20T00:00:00Z", "RELEASE_GATE_APP_TOKEN is not set", 1);
        var good = new Fact(new JsonObject { ["alerts"] = new JsonArray() }, "https://example.invalid/secret", "2026-10-20T00:00:00Z", null, 1);
        string aliasRegistry(string aliasProfile) => "{\"schema\":1,\"specs\":[],\"items\":[" +
            "{\"id\":\"base\",\"title\":\"b\",\"source\":[\"#104\"],\"owner\":[],\"kind\":\"auto\",\"group\":\"Release\",\"check\":{\"name\":\"file-exists\",\"params\":{\"path\":\"global.json\"}},\"profiles\":{\"minor\":\"block\",\"rc\":\"block\",\"final\":\"skip\"}}," +
            $"{{\"id\":\"twin\",\"title\":\"t\",\"source\":[\"#104\"],\"owner\":[],\"kind\":\"auto\",\"group\":\"Release\",\"check\":{{\"name\":\"alias\",\"params\":{{\"item\":\"base\"}}}},\"profiles\":{{\"minor\":\"block\",\"rc\":\"block\",\"final\":\"{aliasProfile}\"}}}}]}}";
        Case("alias: reuses the verdict and facts of its target", () =>
        {
            var aliasReg = Registry.Parse(aliasRegistry("skip"), fx, []).Registry!;
            Fact Exists(bool v) => new(new JsonObject { ["exists"] = v }, "https://example.invalid/f", "2026-10-20T00:00:00Z", null, 1);
            EvalRun GoAlias(bool exists) => Engine.Run(aliasReg, new EvalCtx(new FactsFile(1, "0.14.0", "rc", Sha, "2026-10-20T00:00:00Z", "t", new Dictionary<string, Fact> { ["file:global.json"] = Exists(exists) }), Signoff.Empty, Now), null);
            var ok = GoAlias(true).Results.First(r => r.Item.Id == "twin");
            var bad = GoAlias(false).Results.First(r => r.Item.Id == "twin");
            return Expect(ok.Status == "PASS" && ok.Reason.Contains("same fact as base") && bad.Status == "FAIL", $"{ok.Status} {ok.Reason}; {bad.Status} {bad.Reason}");
        });
        Case("alias: the registry rejects an alias active where its target is skipped", () =>
        {
            var errors = new List<string>();
            var res = Registry.Parse(aliasRegistry("block"), fx, errors);
            return Expect(res.Registry is null && errors.Any(e => e.Contains("alias is active in final but its target 'base' is skipped there")), string.Join("; ", errors));
        });
        Case("attestation: accepted only when the auto fact errored, and the output says it replaced the fact", () =>
        {
            var run = Go(errored, "- [x] attest-secret-scanning — title — evidence: https://example.invalid/review\n");
            var auto = run.Results.First(r => r.Item.Id == "secret-scanning-no-alerts");
            var att = run.Results.First(r => r.Item.Id == "attest-secret-scanning");
            return Expect(auto.Status == "PASS" && auto.Reason.Contains("ATTESTED") && auto.Reason.Contains("replaced the automatic fact") && att.Status == "PASS", $"{auto.Status} {auto.Reason}; {att.Status} {att.Reason}");
        });
        Case("attestation: without an answer the errored fact still fails and the attestation is pending", () =>
        {
            var run = Go(errored, "");
            return Expect(run.Results.First(r => r.Item.Id == "secret-scanning-no-alerts").Status == "FAIL" && run.Results.First(r => r.Item.Id == "attest-secret-scanning").Status == "PENDING", "wrong verdicts");
        });
        Case("attestation: ticked without evidence is not accepted", () =>
        {
            var run = Go(errored, "- [x] attest-secret-scanning — title\n");
            return Expect(run.Results.First(r => r.Item.Id == "secret-scanning-no-alerts").Status == "FAIL", "accepted without evidence");
        });
        Case("attestation: ignored when the auto fact was collected", () =>
        {
            var run = Go(good, "- [x] attest-secret-scanning — title — evidence: https://example.invalid/review\n");
            return Expect(run.Results.First(r => r.Item.Id == "secret-scanning-no-alerts").Status == "PASS" && !run.Results.First(r => r.Item.Id == "secret-scanning-no-alerts").Reason.Contains("ATTESTED") && run.Results.First(r => r.Item.Id == "attest-secret-scanning").Status == "SKIP", "attestation was used although the fact was good");
        });
    }
}
